import{n as e}from"./rolldown-runtime-BgaNhQyE.js";var t,n,r,i=e((()=>{t=`2026-08-15`,n=[{slug:`blogs`,label:`Blogs`,description:`Personal writers, company engineering blogs, and publications that actually explain how modern AI works.`,subsections:[`Individual writers`,`Company engineering blogs`,`Publications`,`Hidden gems`],items:[{name:`Lil'Log — Lilian Weng`,url:`https://lilianweng.github.io/`,blurb:`The best survey-style blog in the field: one long, heavily-cited post every couple of months. Still shipping in 2026 (recursive self-improvement, scaling laws, agent harnesses) after the 2023 "LLM Powered Autonomous Agents" post that half the industry learned agents from.`,tags:[`lilianweng.github.io`,`blog`,`intermediate→advanced`],subsection:`Individual writers`,gem:!1},{name:`Andrej Karpathy — bearblog`,url:`https://karpathy.bearblog.dev/`,blurb:`Where Karpathy actually writes now; the old karpathy.github.io is frozen. Short conceptual essays — "Animals vs Ghosts", "The space of minds", "2025 LLM Year in Review" — that reframe how you think rather than teach a technique.`,tags:[`karpathy.bearblog.dev`,`blog`,`all levels`],subsection:`Individual writers`,gem:!1},{name:`Simon Willison's Weblog`,url:`https://simonwillison.net/`,blurb:`The highest-volume, lowest-hype running log of what LLMs can actually do. Posts near-daily; the annual LLMs year-in-review series is the best single catch-up document that exists.`,tags:[`simonwillison.net`,`blog`,`beginner→intermediate`],subsection:`Individual writers`,gem:!1},{name:`Eugene Yan`,url:`https://eugeneyan.com/writing/`,blurb:`Applied-scientist writing on evals, RecSys, and shipping ML that survives production. Active through 2026 (cybersecurity evals, product evals). Structured and opinionated, never listicle-y.`,tags:[`eugeneyan.com`,`blog`,`intermediate`],subsection:`Individual writers`,gem:!1},{name:`Hamel Husain`,url:`https://hamel.dev/`,blurb:`The evals guy. "Your AI Product Needs Evals", the LLM-as-judge guide, and the sprawling evals FAQ are the reference texts for anyone building an LLM product they're accountable for.`,tags:[`hamel.dev`,`blog`,`intermediate`],subsection:`Individual writers`,gem:!1},{name:`Chip Huyen`,url:`https://huyenchip.com/blog/`,blurb:`Long, systems-level essays — "Agents" (8k words), "Building A Generative AI Platform" — written like textbook chapters. Low frequency, high density; author of the AI Engineering book.`,tags:[`huyenchip.com`,`blog`,`intermediate`],subsection:`Individual writers`,gem:!1},{name:`Sean Goedecke`,url:`https://www.seangoedecke.com/`,blurb:`A staff engineer writing plainly about working with LLMs day to day ("How I use LLMs as a staff engineer in 2026", "When you should lie to the language model"). Best-in-class on the craft and career side rather than the model side.`,tags:[`seangoedecke.com`,`blog`,`beginner→intermediate`],subsection:`Individual writers`,gem:!1},{name:`Nathan Lambert`,url:`https://natolambert.com/writing`,blurb:`His essays and talks outside the newsletter, plus the open RLHF Book. Reads the frontier-lab post-training tea leaves better than anyone; the newsletter half lives at Interconnects.`,tags:[`natolambert.com`,`blog`,`intermediate→advanced`],subsection:`Individual writers`,gem:!1},{name:`Deep (Learning) Focus — Cameron R. Wolfe`,url:`https://cameronrwolfe.substack.com/`,blurb:`Paper-survey posts that read like literature reviews with the jargon removed — "Demystifying Reasoning Models", "The Anatomy of an LLM Benchmark", "Agentic World Models" (2026). To catch up on a subfield in one sitting, start here.`,tags:[`cameronrwolfe.substack.com`,`blog`,`intermediate→advanced`],subsection:`Individual writers`,gem:!1},{name:`Artificial Fintelligence — Finbarr Timbers`,url:`https://www.artfintel.com/`,blurb:`Ex-DeepMind, writes hard-nosed posts on RL, inference economics, and why the thing everyone is excited about won't work. Notably unafraid to be unfashionable.`,tags:[`artfintel.com`,`blog`,`advanced`],subsection:`Individual writers`,gem:!1},{name:`Vicki Boykis`,url:`https://vickiboykis.com/`,blurb:`Embeddings, search, and the sociology of ML work. "What we don't talk about when we talk about building AI apps" is the antidote to demo-driven engineering; still posting through 2026.`,tags:[`vickiboykis.com`,`blog`,`intermediate`],subsection:`Individual writers`,gem:!1},{name:`Ahead of AI — Sebastian Raschka`,url:`https://magazine.sebastianraschka.com/`,blurb:`(The blog only — his book and courses are covered elsewhere on fanout.) "The Big LLM Architecture Comparison" and its 2026 sequels are the clearest side-by-side of what actually changed between open-weight model generations.`,tags:[`magazine.sebastianraschka.com`,`blog`,`intermediate→advanced`],subsection:`Individual writers`,gem:!1},{name:`Sasha Rush`,url:`https://blog.rush-nlp.com/`,blurb:`The Cornell/Hugging Face professor behind The Annotated Transformer and the GPU Puzzles / Transformer Puzzles series. Teaches by making you implement the thing in a notebook.`,tags:[`rush-nlp.com`,`blog`,`advanced`],subsection:`Individual writers`,gem:!1},{name:`Horace He`,url:`https://horace.io/`,blurb:`PyTorch/torch.compile core dev. Tiny site, one landmark post: Making Deep Learning Go Brrrr From First Principles, the compute-vs-bandwidth-vs-overhead model everyone else now cites. (classic, low activity)`,tags:[`horace.io`,`blog`,`advanced`],subsection:`Individual writers`,gem:!1},{name:`Tim Dettmers`,url:`https://timdettmers.com/`,blurb:`"Which GPU for Deep Learning" and the full hardware guide are still the default answer to "what should I buy", plus the QLoRA/bitsandbytes lineage. New posts are rare now. (classic, low activity)`,tags:[`timdettmers.com`,`blog`,`intermediate`],subsection:`Individual writers`,gem:!1},{name:`Gwern Branwen`,url:`https://gwern.net/`,blurb:`Obsessively-edited long-form on scaling, ML history, and everything adjacent. The Scaling Hypothesis is the piece; the site is a rabbit hole by design.`,tags:[`gwern.net`,`essays`,`advanced`],subsection:`Individual writers`,gem:!1},{name:`colah's blog — Chris Olah`,url:`https://colah.github.io/`,blurb:`"Understanding LSTM Networks" and "Visual Information Theory" set the standard for visual explanation. Olah's current work is on Transformer Circuits; the personal blog is now an archive. (classic, inactive)`,tags:[`colah.github.io`,`blog`,`intermediate`],subsection:`Individual writers`,gem:!1},{name:`Jay Alammar`,url:`https://jalammar.github.io/`,blurb:`The Illustrated Transformer / Illustrated Word2vec. He has frozen this blog and moved to newsletter.languagemodels.co — the archive is the reason to bookmark it. (classic, archive)`,tags:[`jalammar.github.io`,`blog`,`beginner`],subsection:`Individual writers`,gem:!1},{name:`Armin Ronacher`,url:`https://lucumr.pocoo.org/`,blurb:`The Flask author turned unusually sharp agent-tooling critic in 2026 — "A Language For Agents", "Better Models: Worse Tools", building the Pi minimal agent. Rare mix of language-design taste and agent pragmatism.`,tags:[`lucumr.pocoo.org`,`blog`,`intermediate`],subsection:`Individual writers`,gem:!1},{name:`Register Spill — Thorsten Ball`,url:`https://registerspill.thorstenball.com/`,blurb:`Weekly links-and-thoughts from the Amp/Sourcegraph engineer who wrote How to Build an Agent. "A New Kind of Code" is the honest version of what agents did to his job.`,tags:[`registerspill.thorstenball.com`,`blog`,`beginner→intermediate`],subsection:`Individual writers`,gem:!1},{name:`Shreya Shankar`,url:`https://www.sh-reya.com/blog/`,blurb:`Berkeley PhD on data quality, LLM pipelines, and why AI projects fail. Start with "Data Flywheels for LLM Applications"; she co-wrote the applied-LLMs essay.`,tags:[`sh-reya.com`,`blog`,`intermediate`],subsection:`Individual writers`,gem:!1},{name:`Aleksa Gordić`,url:`https://www.aleksagordic.com/`,blurb:`Ex-DeepMind, llm.c contributor, now pretraining LLMs. Two monster posts — Inside the Transformer: The Life of a Token and Inside NVIDIA GPUs — cover the stack end to end.`,tags:[`aleksagordic.com`,`blog`,`advanced`],subsection:`Individual writers`,gem:!1},{name:`ezyang's blog — Edward Z. Yang`,url:`http://blog.ezyang.com/`,blurb:`PyTorch core dev. "PyTorch internals" and "Let's talk about the PyTorch dispatcher" are how most people learn the framework's guts; still posting in 2026 (autograd and mutation).`,tags:[`blog.ezyang.com`,`blog`,`advanced`],subsection:`Individual writers`,gem:!1},{name:`kipply's blog`,url:`https://kipply.github.io/blog/`,blurb:`"Transformer Inference Arithmetic" and "LLM Parameter Counting" — the napkin math for latency, memory, and FLOPs that everyone still links. Mirrored at kipp.ly. (classic, inactive)`,tags:[`kipply.github.io`,`blog`,`advanced`],subsection:`Individual writers`,gem:!1},{name:`Hugging Face Blog`,url:`https://huggingface.co/blog`,blurb:`Enormous range, community-contributed. The two must-reads are book-length Spaces: The Ultra-Scale Playbook (distributed training on 500+ GPUs) and The Smol Training Playbook.`,tags:[`huggingface.co`,`company blog`,`all levels`],subsection:`Company engineering blogs`,gem:!1},{name:`vLLM Blog`,url:`https://blog.vllm.ai/`,blurb:`The best free curriculum in inference serving. "Inside vLLM: Anatomy of a High-Throughput LLM Inference System" covers PagedAttention, continuous batching, prefix caching, and speculative decoding in one 41-minute read.`,tags:[`vllm.ai`,`company blog`,`advanced`],subsection:`Company engineering blogs`,gem:!1},{name:`LMSYS Org Blog`,url:`https://www.lmsys.org/blog`,blurb:`SGLang internals plus the Chatbot Arena lineage. Very active in 2026 on pipeline parallelism for million-token contexts, speculative decoding, and the quantization stack.`,tags:[`lmsys.org`,`company blog`,`advanced`],subsection:`Company engineering blogs`,gem:!1},{name:`Modal Blog`,url:`https://modal.com/blog`,blurb:`Serverless GPU infrastructure written up honestly ("How we achieved truly serverless GPUs"). Their GPU Glossary is the CUDA-docs-for-humans reference and worth a bookmark on its own.`,tags:[`modal.com`,`company blog`,`intermediate→advanced`],subsection:`Company engineering blogs`,gem:!1},{name:`Baseten Blog`,url:`https://www.baseten.co/blog/`,blurb:`Model-serving performance work with numbers attached — KV-cache-aware routing, NVIDIA Dynamo, per-model inference write-ups within days of each frontier release.`,tags:[`baseten.co`,`company blog`,`advanced`],subsection:`Company engineering blogs`,gem:!1},{name:`Answer.AI`,url:`https://www.answer.ai/`,blurb:`Jeremy Howard's lab. "You can now train a 70b language model at home" (FSDP+QLoRA) and its deep-dive companion are the template for making frontier techniques run on consumer hardware.`,tags:[`answer.ai`,`company blog`,`intermediate→advanced`],subsection:`Company engineering blogs`,gem:!1},{name:`Hazy Research (Stanford)`,url:`https://hazyresearch.stanford.edu/blog`,blurb:`Chris Ré's group — FlashAttention, ThunderKittens, megakernels. Where "GPUs Go Brrr" came from; still shipping in 2026 (ThunderKittens 2.0).`,tags:[`hazyresearch.stanford.edu`,`lab blog`,`advanced`],subsection:`Company engineering blogs`,gem:!1},{name:`PyTorch Blog`,url:`https://pytorch.org/blog/`,blurb:`Kernel fusion, torch.compile internals, NCCL debugging tools. Skip the release notes and read the deep dives.`,tags:[`pytorch.org`,`company blog`,`advanced`],subsection:`Company engineering blogs`,gem:!1},{name:`Latent Space`,url:`https://www.latent.space/`,blurb:`swyx & Alessio's AI-engineering publication, read as a blog. Best coverage of what the industry is collectively figuring out at any given moment; "The Rise of the AI Engineer" started here.`,tags:[`latent.space`,`blog`,`intermediate`],subsection:`Company engineering blogs`,gem:!1},{name:`The Gradient`,url:`https://thegradient.pub/`,blurb:`Long-form, editorially-reviewed essays on ML research and its implications — the closest thing the field has to a serious magazine. Slow publishing pace, deep archive.`,tags:[`thegradient.pub`,`magazine`,`intermediate`],subsection:`Publications`,gem:!1},{name:`Transformer Circuits Thread`,url:`https://transformer-circuits.pub/`,blurb:`Anthropic's interpretability venue, in the Distill house style. "A Mathematical Framework for Transformer Circuits" and the 2025 circuit-tracing work are where mech-interp vocabulary comes from.`,tags:[`transformer-circuits.pub`,`research publication`,`advanced`],subsection:`Publications`,gem:!1},{name:`Epoch AI — Gradient Updates`,url:`https://epoch.ai/gradient-updates`,blurb:`Weekly data-driven analysis of compute, benchmarks, and capability trends. The one place to get an actual number instead of a vibe.`,tags:[`epoch.ai`,`research publication`,`intermediate`],subsection:`Publications`,gem:!1},{name:`SemiAnalysis`,url:`https://semianalysis.com/`,blurb:`Dylan Patel's hardware and datacenter reporting — H100 cluster topologies, GPU cloud economics, multi-datacenter training. Partly paywalled; the free posts still beat most paid research.`,tags:[`semianalysis.com`,`industry analysis`,`intermediate→advanced`],subsection:`Publications`,gem:!1},{name:`Quanta Magazine — AI`,url:`https://www.quantamagazine.org/tag/artificial-intelligence/`,blurb:`Science journalism that doesn't dumb things down. Their 2026 run on AI in mathematics and the reasoning debate is the best non-technical writing on what these systems actually do.`,tags:[`quantamagazine.org`,`magazine`,`beginner→intermediate`],subsection:`Publications`,gem:!1},{name:`Distill`,url:`https://distill.pub/`,blurb:`The interactive-explanation journal that raised everyone's standards. Ceased publication in 2021; "Research Debt", the Circuits thread, and Feature Visualization remain required reading. (classic, inactive)`,tags:[`distill.pub`,`research publication`,`intermediate`],subsection:`Publications`,gem:!1},{name:`Doubleword Blog`,url:`https://blog.doubleword.ai/`,blurb:`The most under-followed inference blog going. "What happens when a GPU reads memory" (following one SASS instruction through an RTX 4090), "Reverse-engineering NVIDIA's cuda-checkpoint", "You Could Have Come Up With Kimi Delta Attention" — first-principles teaching, not marketing. Several posts a month in 2026.`,tags:[`blog.doubleword.ai`,`company blog`,`advanced`],subsection:`Hidden gems`,gem:!0},{name:`fleetwood.dev`,url:`https://fleetwood.dev/`,blurb:`Christopher Fleetwood on inference internals — "Layer Normalization as fast as possible", domain-specific architectures for AI inference. Short posts, no filler, unusual willingness to show the assembly.`,tags:[`fleetwood.dev`,`blog`,`advanced`],subsection:`Hidden gems`,gem:!0},{name:`Theia Vogel`,url:`https://vgel.me/posts/`,blurb:`Independent, playful, deeply technical: "How to make LLMs go fast", "Representation Engineering Mistral-7B an Acid Trip", small-model introspection experiments. Ships original results rather than summaries.`,tags:[`vgel.me`,`blog`,`advanced`],subsection:`Hidden gems`,gem:!0},{name:`Manifest AI`,url:`https://manifestai.com/`,blurb:`Jacob Buckman's lab publishing its research (power attention, rethinking attention for long context) as readable articles rather than only arXiv dumps. Rare: a startup showing its architectural reasoning in public.`,tags:[`manifestai.com`,`lab blog`,`advanced`],subsection:`Hidden gems`,gem:!0},{name:`Neel Nanda`,url:`https://www.neelnanda.io/mechanistic-interpretability`,blurb:`The mech-interp on-ramp — quickstart guide, concrete first steps, "how to become a researcher". Revised into 2026, which matters in a field moving this fast.`,tags:[`neelnanda.io`,`blog/guide`,`intermediate→advanced`],subsection:`Hidden gems`,gem:!0},{name:`Geoffrey Litt`,url:`https://www.geoffreylitt.com/`,blurb:`Ink & Switch researcher on malleable software and end-user programming in the LLM era. The best writing on what personal software becomes when anyone can generate their own tools.`,tags:[`geoffreylitt.com`,`blog`,`intermediate`],subsection:`Hidden gems`,gem:!0}],totalItems:45},{slug:`articles`,label:`Articles`,description:`Canonical standalone essays — the read-once, think-differently pieces from the Bitter Lesson to the agents era.`,subsections:[`Foundations`,`Scaling & strategy`,`Engineering practice`,`Agents & the 2025–26 era`,`Hidden gems`],items:[{name:`The Illustrated Transformer`,url:`https://jalammar.github.io/illustrated-transformer/`,blurb:`Jay Alammar, 2018. The diagrams that taught a generation what Q, K, and V are. Still the fastest path from zero to a working picture of attention. Pairs well with bbycroft's 3D LLM visualization if the tensor shapes never quite clicked.`,tags:[`jalammar.github.io`,`explainer`,`beginner`],subsection:`Foundations`,gem:!1},{name:`The Annotated Transformer`,url:`https://nlp.seas.harvard.edu/annotated-transformer/`,blurb:`Harvard NLP (Sasha Rush et al.). "Attention Is All You Need" rewritten line-by-line as runnable PyTorch. Read it after the Illustrated Transformer, with the notebook open; the 2018 original is still up.`,tags:[`nlp.seas.harvard.edu`,`explainer/code`,`intermediate`],subsection:`Foundations`,gem:!1},{name:`Transformers from scratch`,url:`https://peterbloem.nl/blog/transformers`,blurb:`Peter Bloem. The mathematically honest version — builds self-attention from the dot product up and explains why each piece exists. The bridge between feeling like you understand it and being able to derive it. (classic, still accurate)`,tags:[`peterbloem.nl`,`explainer`,`intermediate`],subsection:`Foundations`,gem:!1},{name:`The Unreasonable Effectiveness of Recurrent Neural Networks`,url:`https://karpathy.github.io/2015/05/21/rnn-effectiveness/`,blurb:`Karpathy, 2015. The post where character-level generation stopped looking like a toy. Historically load-bearing: this is the "oh, next-token prediction is doing something real" moment, five years early. (classic)`,tags:[`karpathy.github.io`,`essay`,`beginner`],subsection:`Foundations`,gem:!1},{name:`A Mathematical Framework for Transformer Circuits`,url:`https://transformer-circuits.pub/2021/framework/`,blurb:`Elhage et al., Anthropic. Introduces the residual-stream view, QK/OV circuits, and induction heads. Dense, but it's the source of the vocabulary every interpretability conversation now assumes you have.`,tags:[`transformer-circuits.pub`,`research article`,`advanced`],subsection:`Foundations`,gem:!1},{name:`Transformer Inference Arithmetic`,url:`https://kipply.github.io/blog/transformer-inference-arithmetic/`,blurb:`kipply, 2022. The napkin math for KV cache size, memory bandwidth limits, and where your latency actually goes. Every serving-cost argument since has been a footnote to this. (classic)`,tags:[`kipply.github.io`,`explainer`,`advanced`],subsection:`Foundations`,gem:!1},{name:`Making Deep Learning Go Brrrr From First Principles`,url:`https://horace.io/brrr_intro.html`,blurb:`Horace He (PyTorch). Compute-bound vs memory-bandwidth-bound vs overhead-bound — the three-way diagnosis that tells you whether fusing kernels will help or you're about to waste a week. (classic, still the standard reference)`,tags:[`horace.io`,`essay`,`advanced`],subsection:`Foundations`,gem:!1},{name:`The Bitter Lesson`,url:`http://www.incompleteideas.net/IncIdeas/BitterLesson.html`,blurb:`Rich Sutton, 2019. Roughly 1,100 words arguing that general methods leveraging computation beat hand-engineered human knowledge every time, and that we keep relearning it. The most-cited and most-misread essay in the field — read the original, not someone's summary of it.`,tags:[`incompleteideas.net`,`essay`,`all levels`],subsection:`Scaling & strategy`,gem:!1},{name:`The Scaling Hypothesis`,url:`https://gwern.net/scaling-hypothesis`,blurb:`Gwern, 2020. Written in the shock of GPT-3, laying out the case that intelligence might mostly be a compute-allocation problem — before that was consensus. The intellectual bridge from Sutton to the scaling-law era; see also the 2022 revisit.`,tags:[`gwern.net`,`essay`,`intermediate→advanced`],subsection:`Scaling & strategy`,gem:!1},{name:`Software 2.0`,url:`https://karpathy.medium.com/software-2-0-a64152b37c35`,blurb:`Karpathy, 2017. Weights as the new source code, datasets as the new codebase, gradient descent as the compiler. Nearly a decade old and still the cleanest framing of what changed about writing software. (classic)`,tags:[`karpathy.medium.com`,`essay`,`all levels`],subsection:`Scaling & strategy`,gem:!1},{name:`The "it" in AI models is the dataset`,url:`https://nonint.com/2023/06/10/the-it-in-ai-models-is-the-dataset/`,blurb:`James Betker (OpenAI), 2023. A few hundred words claiming model behavior is determined by the data, not the architecture — two models trained long enough on the same corpus converge. Short, unhedged, and load-bearing for how people now argue about differentiation.`,tags:[`nonint.com`,`essay`,`intermediate`],subsection:`Scaling & strategy`,gem:!1},{name:`Situational Awareness: The Decade Ahead`,url:`https://situational-awareness.ai/`,blurb:`Leopold Aschenbrenner, 2024. Book-length trend extrapolation to AGI and its geopolitics. Read it as the most rigorous statement of the aggressive-timeline view rather than as prediction — people are now scoring its calls.`,tags:[`situational-awareness.ai`,`long-form essay`,`intermediate`],subsection:`Scaling & strategy`,gem:!1},{name:`Machines of Loving Grace`,url:`https://darioamodei.com/essay/machines-of-loving-grace`,blurb:`Dario Amodei, 2024. Anthropic's CEO deliberately describing what goes right — compressed biology, mental health, development economics. Whatever you make of the timeline, it's the most concrete optimistic case anyone has written down.`,tags:[`darioamodei.com`,`essay`,`all levels`],subsection:`Scaling & strategy`,gem:!1},{name:`The Rise of the AI Engineer`,url:`https://www.latent.space/p/ai-engineer`,blurb:`swyx, 2023. Named the role most people reading this archive are moving into: the engineer who works with foundation models from the outside rather than training them. Correctly called a job category into existence.`,tags:[`latent.space`,`essay`,`beginner`],subsection:`Scaling & strategy`,gem:!1},{name:`What We Learned from a Year of Building with LLMs`,url:`https://applied-llms.org/`,blurb:`Yan, Bischof, Frye, Husain, Liu, Shankar (2024). Six practitioners, three parts (tactical/operational/strategic), zero vendor pitch. The tactical section alone — evals, RAG vs fine-tuning, structured output, when to hedge — saves a quarter of trial and error. Also on O'Reilly Radar.`,tags:[`applied-llms.org`,`field report`,`intermediate`],subsection:`Engineering practice`,gem:!1},{name:`Your AI Product Needs Evals`,url:`https://hamel.dev/blog/posts/evals/`,blurb:`Hamel Husain. The argument that eval infrastructure is the product work, plus the concrete loop: look at your data, write assertions, build the flywheel. Follow with his LLM-as-a-Judge guide and the enormous evals FAQ.`,tags:[`hamel.dev`,`essay`,`intermediate`],subsection:`Engineering practice`,gem:!1},{name:`Building A Generative AI Platform`,url:`https://huyenchip.com/2024/07/25/genai-platform.html`,blurb:`Chip Huyen. Builds the reference architecture one layer at a time — context construction, guardrails, routing, caching, observability — in the order teams actually add them. The best answer to "what does this system look like at the end?"`,tags:[`huyenchip.com`,`architecture guide`,`intermediate`],subsection:`Engineering practice`,gem:!1},{name:`A Hacker's Guide to Language Models`,url:`https://fastai.github.io/lm-hackers/lm-hackers.html`,blurb:`Jeremy Howard, 2023. One notebook from "what is a language model" through fine-tuning and running open models locally, in his usual code-first register. The companion to the widely-shared talk of the same name.`,tags:[`fastai.github.io`,`tutorial/essay`,`intermediate`],subsection:`Engineering practice`,gem:!1},{name:`The Ultra-Scale Playbook`,url:`https://huggingface.co/spaces/nanotron/ultrascale-playbook`,blurb:`Hugging Face / nanotron. Book-length, interactive treatment of training LLMs across hundreds of GPUs: data, tensor, pipeline, and context parallelism, with the memory arithmetic behind each choice. Free, and better than most paid courses.`,tags:[`huggingface.co`,`long-form guide`,`advanced`],subsection:`Engineering practice`,gem:!1},{name:`The Smol Training Playbook`,url:`https://huggingface.co/spaces/HuggingFaceTB/smol-training-playbook`,blurb:`Hugging Face. The honest end-to-end account of actually training a model — ablations, data mixtures, the failures — from the SmolLM team. Read alongside Ultra-Scale: that one is the physics, this is the lab notebook.`,tags:[`huggingface.co`,`long-form guide`,`advanced`],subsection:`Engineering practice`,gem:!1},{name:`Inside vLLM: Anatomy of a High-Throughput LLM Inference System`,url:`https://blog.vllm.ai/2025/09/05/anatomy-of-vllm.html`,blurb:`Aleksa Gordić, 2025. Forty minutes connecting PagedAttention, continuous batching, prefix caching, speculative decoding, scheduling, and multi-GPU serving into one narrative. The best free explanation of how a modern inference server works.`,tags:[`blog.vllm.ai`,`deep dive`,`advanced`],subsection:`Engineering practice`,gem:!1},{name:`Agents`,url:`https://huyenchip.com/2025/01/07/agents.html`,blurb:`Chip Huyen, 2025. Eight thousand words on tools, planning, failure modes, and evaluation — the textbook-chapter version rather than a framework tutorial. Read this before choosing an agent framework, not after.`,tags:[`huyenchip.com`,`long-form essay`,`intermediate`],subsection:`Agents & the 2025–26 era`,gem:!1},{name:`The Second Half`,url:`https://ysymyth.github.io/The-Second-Half/`,blurb:`Shunyu Yao (ReAct author), 2025. Argues the era of inventing methods is closing and the era of defining tasks and evaluation is opening. Short, and it reoriented a lot of research and product agendas in one afternoon.`,tags:[`ysymyth.github.io`,`essay`,`intermediate→advanced`],subsection:`Agents & the 2025–26 era`,gem:!1},{name:`Don't Build Multi-Agents`,url:`https://cognition.ai/blog/dont-build-multi-agents`,blurb:`Walden Yan / Cognition, 2025. Context fragmentation and conflicting implicit decisions as the reason parallel subagents produce incoherent work. Read back-to-back with the next entry — they landed a day apart and disagree productively.`,tags:[`cognition.ai`,`essay`,`intermediate`],subsection:`Agents & the 2025–26 era`,gem:!1},{name:`How we built our multi-agent research system`,url:`https://www.anthropic.com/engineering/multi-agent-research-system`,blurb:`Anthropic, 2025. The opposite conclusion, with the orchestrator/subagent architecture, token economics, and the evaluation and production problems spelled out. (Engineering post, not the prompting docs.)`,tags:[`anthropic.com`,`engineering write-up`,`intermediate→advanced`],subsection:`Agents & the 2025–26 era`,gem:!1},{name:`Effective context engineering for AI agents`,url:`https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents`,blurb:`Anthropic, 2025. The piece that made "context engineering" the successor term to prompt engineering: context as a finite budget to be curated, compacted, and offloaded. Pairs with their long-running-agent harness post.`,tags:[`anthropic.com`,`engineering write-up`,`intermediate`],subsection:`Agents & the 2025–26 era`,gem:!1},{name:`12-Factor Agents`,url:`https://github.com/humanlayer/12-factor-agents`,blurb:`Dex Horthy, 2025. Twelve factors for reliable LLM applications, explicitly modeled on the 12-factor app — own your prompts, own your control flow, treat agents as stateless reducers. The most actionable "stop shipping demos" document of the agent era.`,tags:[`github.com/humanlayer`,`principles`,`intermediate`],subsection:`Agents & the 2025–26 era`,gem:!1},{name:`2025: The year in LLMs`,url:`https://simonwillison.net/2025/Dec/31/the-year-in-llms/`,blurb:`Simon Willison. Twenty-six sections covering reasoning models, coding agents, Chinese open-weight releases, and the price collapse. The best way to reconstruct a year you weren't paying attention to; the whole annual series is worth the afternoon.`,tags:[`simonwillison.net`,`review`,`beginner→intermediate`],subsection:`Agents & the 2025–26 era`,gem:!1},{name:`Animals vs Ghosts`,url:`https://karpathy.bearblog.dev/animals-vs-ghosts/`,blurb:`Karpathy, 2025. LLMs aren't evolved animals, they're "ghosts" — imitative distillations of humanity, with a different set of instincts and failure modes. A short reframing that makes a lot of anthropomorphic confusion dissolve.`,tags:[`karpathy.bearblog.dev`,`essay`,`all levels`],subsection:`Agents & the 2025–26 era`,gem:!1},{name:`A New Kind of Code`,url:`https://registerspill.thorstenball.com/p/a-new-kind-of-code`,blurb:`Thorsten Ball, 2025. An experienced engineer being honest about what agentic coding did to his relationship with his own craft — neither doom nor hype. The one to read when the productivity discourse gets exhausting.`,tags:[`registerspill.thorstenball.com`,`essay`,`all levels`],subsection:`Hidden gems`,gem:!0},{name:`You Could Have Come Up With Kimi Delta Attention`,url:`https://blog.doubleword.ai/you-could-have-come-up-with-kimi-delta-attention`,blurb:`Jamie Dborin, 2026. Derives the DeltaNet family of linear attention mechanisms so each step feels inevitable rather than magic. A model for explaining a new architecture without a single "as is well known".`,tags:[`blog.doubleword.ai`,`explainer`,`advanced`],subsection:`Hidden gems`,gem:!0},{name:`The case for disaggregated LLM serving`,url:`https://blog.doubleword.ai/when-to-disaggregate`,blurb:`Fergus Finn, 2026. Three checkable conditions under which splitting prefill from decode is never worse, plus an inventory-theory model of traffic drift and cold starts. Rare: an infra post that hands you a decision rule instead of a benchmark.`,tags:[`blog.doubleword.ai`,`analysis`,`advanced`],subsection:`Hidden gems`,gem:!0},{name:`Inside NVIDIA GPUs: Anatomy of high performance matmul kernels`,url:`https://www.aleksagordic.com/blog/matmul`,blurb:`Aleksa Gordić. Memory hierarchy to tiling to tensor cores, one continuous explanation of why fast matmul kernels look the way they do. Read it before attempting CUDA yourself.`,tags:[`aleksagordic.com`,`deep dive`,`advanced`],subsection:`Hidden gems`,gem:!0},{name:`Representation Engineering Mistral-7B an Acid Trip`,url:`https://vgel.me/posts/representation-engineering/`,blurb:`Theia Vogel, 2024. Finds control vectors in activation space and steers a model's mood by adding them at inference. Original work, funny framing, and the clearest hands-on introduction to activation steering.`,tags:[`vgel.me`,`experiment write-up`,`advanced`],subsection:`Hidden gems`,gem:!0},{name:`Data Flywheels for LLM Applications`,url:`https://www.sh-reya.com/blog/ai-engineering-flywheel/`,blurb:`Shreya Shankar, 2024. Why the durable advantage in an LLM product is the loop turning production traffic into better evals and better data, not the prompt. Underread relative to how much it should shape a roadmap.`,tags:[`sh-reya.com`,`essay`,`intermediate`],subsection:`Hidden gems`,gem:!0}],totalItems:35},{slug:`newsletters`,label:`Newsletters`,description:`Substack and beyond — research analysis, engineering digests, China coverage. Cadence and pricing noted.`,subsections:[`Research & frontier analysis`,`Engineering & practice`,`News digests`,`Medium & publications`,`Hidden gems`],items:[{name:`Interconnects`,url:`https://www.interconnects.ai/`,blurb:`Nathan Lambert (Allen Institute for AI, post-training lead) on RLHF, open models, and what the frontier labs are actually doing differently. The best single source for understanding why a model behaves the way it does rather than what it scored. Several posts a week, free with a paid tier for interviews and deeper dives.`,tags:[`substack`,`newsletter`,`advanced`],subsection:`Research & frontier analysis`,gem:!1},{name:`Import AI`,url:`https://importai.substack.com/`,blurb:`Jack Clark (Anthropic co-founder, ex-OpenAI policy) has run this weekly since 2016: paper summaries wrapped in genuinely serious analysis of where capability and policy are heading, plus a short science-fiction vignette at the end. Weekly on Mondays, free. If you subscribe to exactly one AI newsletter, this is the defensible choice.`,tags:[`substack`,`newsletter`,`intermediate`],subsection:`Research & frontier analysis`,gem:!1},{name:`Ahead of AI`,url:`https://magazine.sebastianraschka.com/`,blurb:`Sebastian Raschka's long-form deep dives on LLM architecture, training, and reasoning — the ones with the hand-drawn architecture diagrams everyone reposts. Roughly every 3-4 weeks, free with a paid tier. Slower cadence than most, but each issue is closer to a book chapter than an email.`,tags:[`substack`,`newsletter`,`advanced`],subsection:`Research & frontier analysis`,gem:!1},{name:`Deep (Learning) Focus`,url:`https://cameronrwolfe.substack.com/`,blurb:`Cameron R. Wolfe (PhD, Netflix) writes one very long, very well-cited explainer per month on a single topic: RAG, reasoning models, LLM-as-judge, scaling laws. Reads like a survey paper you'd actually finish. Monthly-ish, free. Excellent for filling in a topic properly rather than skimming twelve takes on it.`,tags:[`substack`,`newsletter`,`advanced`],subsection:`Research & frontier analysis`,gem:!1},{name:`Turing Post`,url:`https://www.turingpost.com/`,blurb:`Ksenia Se's research-to-practice newsletter: technique explainers ("what is X and when would you use it"), model release breakdowns, and a solid weekly research roundup. Multiple issues weekly, free with paid tier. Good middle ground between digest and deep dive.`,tags:[`web`,`newsletter`,`intermediate`],subsection:`Research & frontier analysis`,gem:!1},{name:`TheSequence`,url:`https://thesequence.substack.com/`,blurb:`Jesus Rodriguez publishes nearly daily: alternating educational series (a multi-part walk through evals, agents, or interpretability) with paper reviews and engineering posts. Very high volume, free with paid tier. Skim the series, read the ones matching your current problem.`,tags:[`substack`,`newsletter`,`intermediate`],subsection:`Research & frontier analysis`,gem:!1},{name:`Gradient Updates (Epoch AI)`,url:`https://epoch.ai/gradient-updates`,blurb:`Epoch AI's weekly, from the team that maintains the definitive datasets on training compute, model scaling, and AI economics. Quantitative and unusually careful about uncertainty — the antidote to vibes-based capability forecasting. Weekly, free. (Substack mirror: epochai.substack.com)`,tags:[`web`,`newsletter`,`intermediate`],subsection:`Research & frontier analysis`,gem:!1},{name:`Exploring Language Models`,url:`https://newsletter.maartengrootendorst.com/`,blurb:`Maarten Grootendorst (creator of BERTopic) makes visual guides to LLM internals — mixture of experts, quantization, reasoning — where the illustrations do the actual explaining. Irregular, roughly monthly, free. Best-in-class if you learn from diagrams.`,tags:[`substack`,`newsletter`,`intermediate`],subsection:`Research & frontier analysis`,gem:!1},{name:`The Algorithmic Bridge`,url:`https://www.thealgorithmicbridge.com/`,blurb:`Alberto Romero writes the skeptical-but-not-cynical commentary track on frontier releases: what a launch actually demonstrated versus what the blog post claimed. Weekly-plus, free with paid tier. Useful as a counterweight when the timeline is uniformly excited.`,tags:[`substack`,`newsletter`,`intermediate`],subsection:`Research & frontier analysis`,gem:!1},{name:`Air Street Press`,url:`https://press.airstreet.com/`,blurb:'Nathan Benaich (Air Street Capital) and team — the people behind the annual State of AI Report. Long essays on AI compute, European AI, and industry structure, plus the "Guide to AI" roundups. Every week or two, free. The annual report alone justifies subscribing. (Note: the old `guidetoai.substack.com` has been dormant since 2020 — this is the live home.)',tags:[`substack`,`newsletter`,`intermediate`],subsection:`Research & frontier analysis`,gem:!1},{name:`The Gradient`,url:`https://thegradientpub.substack.com/`,blurb:`Long-form essays and interviews on ML research, historically excellent and widely cited. Now sporadic — a handful of posts in 2025-2026, most recently February 2026. Subscribe for the archive and the occasional new piece, not for a regular cadence.`,tags:[`substack`,`newsletter`,`advanced`],subsection:`Research & frontier analysis`,gem:!1},{name:`Artificial Fintelligence`,url:`https://www.artfintel.com/`,blurb:`Finbarr Timbers (ex-DeepMind) on the economics and engineering of inference: what serving actually costs, how batching and speculative decoding change the math. Dormant since June 2025, but the back catalogue on inference economics remains some of the clearest writing on the subject. Read the archive.`,tags:[`substack`,`newsletter`,`advanced`],subsection:`Research & frontier analysis`,gem:!1},{name:`Davis Summarizes Papers`,url:`https://dblalock.substack.com/`,blurb:`Davis Blalock's ruthlessly efficient arXiv digest — dozens of papers per issue, each in a few sentences with an honest "is this real" verdict. Inactive since August 2024 (classic, inactive). Still worth mining the archive to learn how to triage papers fast.`,tags:[`substack`,`newsletter`,`advanced`],subsection:`Research & frontier analysis`,gem:!1},{name:`NLP News`,url:`https://newsletter.ruder.io/`,blurb:`Sebastian Ruder's newsletter, the canonical NLP research digest of the 2018-2023 era. Inactive since May 2024 (classic, inactive). The archive is a genuinely good way to understand how the field got from word embeddings to instruction tuning.`,tags:[`substack`,`newsletter`,`advanced`],subsection:`Research & frontier analysis`,gem:!1},{name:`Latent Space`,url:`https://www.latent.space/`,blurb:`swyx and Alessio Fanelli's newsletter and podcast — the publication that coined "AI Engineer" and effectively defined the job. Interviews with people shipping LLM products, plus conference talk writeups and infrastructure deep dives. Several times a week, free with paid tier. The single most on-target subscription for a software engineer moving into AI engineering.`,tags:[`substack`,`newsletter`,`intermediate`],subsection:`Engineering & practice`,gem:!1},{name:`The Kaitchup — AI on a Budget`,url:`https://kaitchup.substack.com/`,blurb:`Benjamin Marie on fine-tuning, quantization, LoRA, and running capable models on consumer or single-GPU hardware, with reproducible notebooks and actual benchmark numbers. Several posts a week, mostly paid. The most hands-on newsletter here if you train or serve models yourself.`,tags:[`substack`,`newsletter`,`advanced`],subsection:`Engineering & practice`,gem:!1},{name:`Hamel Husain's Substack`,url:`https://hamelhusain.substack.com/`,blurb:`Hamel Husain is the person most responsible for the current practitioner consensus on LLM evals — error analysis first, custom metrics over generic ones, look at your data. Publishes rarely (a few times a year), free. Low volume, extremely high hit rate; subscribe and read everything he sends.`,tags:[`substack`,`newsletter`,`intermediate`],subsection:`Engineering & practice`,gem:!1},{name:`Gradient Flow`,url:`https://gradientflow.substack.com/`,blurb:`Ben Lorica (ex-O'Reilly Chief Data Scientist, co-chair of the Ray and AI conferences) on the data-and-AI infrastructure layer: agent architectures, retrieval systems, what enterprises are actually deploying. Weekly, free. Strong industry-survey angle.`,tags:[`substack`,`newsletter`,`intermediate`],subsection:`Engineering & practice`,gem:!1},{name:`Deep Learning Weekly`,url:`https://www.deeplearningweekly.com/`,blurb:`A structured weekly roundup split into industry news, learning resources, papers, and code repos. Less breathless than the daily briefs and better organized for actually saving links. Weekly Thursdays, free.`,tags:[`substack`,`digest`,`intermediate`],subsection:`Engineering & practice`,gem:!1},{name:`Decoding AI Magazine`,url:`https://www.decodingai.com/`,blurb:`Paul Iusztin (formerly "Decoding ML") on end-to-end LLM system engineering: RAG pipelines, feature/training/inference architecture, agent deployment. Weekly, free with paid tier. Code-heavy and oriented toward people building the full stack, not just prompting.`,tags:[`substack`,`newsletter`,`intermediate`],subsection:`Engineering & practice`,gem:!1},{name:`AI by Hand`,url:`https://www.byhand.ai/`,blurb:`Prof. Tom Yeh has you work transformers, backprop, and attention by hand on paper before touching code. Frequent short exercises, free with paid workbook tier. Sounds gimmicky; is the fastest way to stop hand-waving about what a matrix multiply is doing in your model.`,tags:[`substack`,`newsletter`,`beginner`],subsection:`Engineering & practice`,gem:!1},{name:`The AI Evaluation Substack`,url:`https://aievaluation.substack.com/`,blurb:`Focused entirely on evaluating LLMs and agents — benchmark design, contamination, judge reliability, what a score actually tells you. Roughly monthly, free. Narrow by design, and evals are where most AI engineering projects quietly fail.`,tags:[`substack`,`newsletter`,`intermediate`],subsection:`Engineering & practice`,gem:!1},{name:`Eugene Yan`,url:`https://eugeneyan.com/subscribe/`,blurb:`Principal applied scientist at Amazon, and a co-author of the Applied LLMs writeup. Writes on recsys, LLM patterns, evals, and the unglamorous parts of shipping ML. Occasional, free. Essays land somewhere between a blog post and internal engineering documentation.`,tags:[`web`,`newsletter`,`intermediate`],subsection:`Engineering & practice`,gem:!1},{name:`Chain of Thought (Every)`,url:`https://every.to/chain-of-thought`,blurb:`Dan Shipper's column on actually working with AI daily — workflows, tool comparisons, and long interviews with model researchers. Weekly, part of Every's paid bundle with free posts. Best on the "how do I restructure my work around this" question rather than the technology itself.`,tags:[`web`,`newsletter`,`beginner`],subsection:`Engineering & practice`,gem:!1},{name:`The Pragmatic Engineer`,url:`https://newsletter.pragmaticengineer.com/`,blurb:`Gergely Orosz reports on what actually happens inside engineering organizations, and since 2024 a large share of that is AI: how teams adopt coding agents, what AI hiring looks like, which claims survive contact with production. Twice weekly, paid (with free issues). Not an AI newsletter per se — but the most useful one for the career transition around it.`,tags:[`substack`,`newsletter`,`intermediate`],subsection:`Engineering & practice`,gem:!1},{name:`TLDR AI`,url:`https://tldr.tech/ai`,blurb:`The default weekday brief: headlines with one-to-two-sentence summaries across models, products, and research. Five minutes, free, ad-supported. Deliberately shallow — it tells you that something happened, never why it matters.`,tags:[`web`,`digest`,`beginner`],subsection:`News digests`,gem:!1},{name:`AlphaSignal`,url:`https://alphasignal.ai/newsletter`,blurb:`The highest signal-per-sentence option for ML engineers: trending papers, new repos, model releases, almost no filler and no lifestyle content. Near-daily, free. If you only want the technical half of the news, this is the one.`,tags:[`web`,`digest`,`intermediate`],subsection:`News digests`,gem:!1},{name:`The Batch`,url:`https://www.deeplearning.ai/the-batch`,blurb:`DeepLearning.AI's weekly, opening with a letter from Andrew Ng and followed by research and industry items explained with an educator's patience. Weekly Wednesdays, free. Ng's letters are often the most quotable thing in AI that week.`,tags:[`web`,`newsletter`,`beginner`],subsection:`News digests`,gem:!1},{name:`Last Week in AI`,url:`https://lastweekin.ai/`,blurb:`The comprehensive weekly catch-up, with a companion podcast. Roughly weekly, free. The right tool for backfilling a week (or a vacation) you missed — it aims for coverage rather than curation.`,tags:[`substack`,`digest`,`intermediate`],subsection:`News digests`,gem:!1},{name:`AI News (smol.ai)`,url:`https://news.smol.ai/`,blurb:`swyx's automated-but-curated daily: AI summaries of the day's Discords, subreddits, and Twitter, with the raw links kept. Daily, free. Unusually good at catching what practitioners are arguing about before it reaches the news cycle. Long — skim the top summary.`,tags:[`web`,`digest`,`advanced`],subsection:`News digests`,gem:!1},{name:`Ben's Bites`,url:`https://www.bensbites.com/`,blurb:`Ben Tossell's daily, now leaning more toward practical how-to and tool tutorials than pure news. Daily, free. Better framed as "learn to apply AI" than "track AI".`,tags:[`substack`,`digest`,`beginner`],subsection:`News digests`,gem:!1},{name:`The Neuron`,url:`https://www.theneurondaily.com/`,blurb:`Chatty, meme-friendly daily brief covering the same ground as TLDR with more personality (since acquired by TechnologyAdvice). Daily, free. Pick it over TLDR if voice is what keeps you opening emails.`,tags:[`web`,`digest`,`beginner`],subsection:`News digests`,gem:!1},{name:`The Rundown AI`,url:`https://www.therundown.ai/`,blurb:`Lead story explained in plain language, then quick hits and tool roundups. Daily, free, noticeably sponsor-heavy. Aimed at professionals who need to sound informed rather than build things.`,tags:[`web`,`digest`,`beginner`],subsection:`News digests`,gem:!1},{name:`Rohan's Bytes`,url:`https://www.rohan-paul.com/`,blurb:`Rohan Paul's near-daily digest of AI papers and engineering news, aimed at people who read arXiv for fun. Daily-ish, free with paid tier. Denser and more research-tilted than the mainstream dailies.`,tags:[`substack`,`digest`,`advanced`],subsection:`News digests`,gem:!1},{name:`Towards Data Science`,url:`https://towardsdatascience.com/`,blurb:`Independent since February 2025, with an editorial team and an author payment program. Publishes daily, free to read, and the 2026 mix is heavily agentic engineering, RAG, and evals rather than the old sklearn-tutorial material. Editorial quality is meaningfully higher post-split.`,tags:[`web`,`publication`,`intermediate`],subsection:`Medium & publications`,gem:!1},{name:`Data Science Collective`,url:`https://medium.com/data-science-collective`,blurb:`Founded in early 2025 and now the largest AI/ML publication remaining on Medium, absorbing a lot of the writers TDS's departure displaced. Publishes many times daily, free with Medium paywall on some posts. Quality is uneven — follow individual authors, not the firehose.`,tags:[`medium`,`publication`,`intermediate`],subsection:`Medium & publications`,gem:!1},{name:`Towards AI`,url:`https://pub.towardsai.net/`,blurb:`Long-running Medium publication with a companion site and a weekly "LAI" issue that reads like a curated newsletter. Daily, mostly free. Stronger on tutorials and LLM engineering walkthroughs than on original research commentary.`,tags:[`medium`,`publication`,`intermediate`],subsection:`Medium & publications`,gem:!1},{name:`LLMs Research`,url:`https://llmsresearch.substack.com/`,blurb:`Spots emerging LLM research patterns early and open-sources implementations of the papers it covers — the "here's the code" step almost no paper digest bothers with. Irregular (a few issues a year in 2026), free. Worth it for the implementations alone.`,tags:[`substack`,`newsletter`,`advanced`],subsection:`Hidden gems`,gem:!0},{name:`This Week on arXiv`,url:`https://thisweekonarxiv.substack.com/`,blurb:`Siavash Yasini's practitioner-friendly AI/ML arXiv digest, plus occasional crash-course posts (the LLM evaluation-metrics series is genuinely good). Slowed noticeably — last issue April 2026 — but the archive is a clean model for how to read papers as an engineer.`,tags:[`substack`,`digest`,`intermediate`],subsection:`Hidden gems`,gem:!0},{name:`AI Tidbits`,url:`https://www.aitidbits.ai/`,blurb:`Sahar Mor's practitioner-angle coverage of new capabilities and what they unlock for builders. Now sporadic (last issue April 2026), free with paid tier. Good archive on early agent and multimodal tooling.`,tags:[`substack`,`newsletter`,`intermediate`],subsection:`Hidden gems`,gem:!0},{name:`Artificial Analysis`,url:`https://artificialanalysis.ai/trends`,blurb:`Not a newsletter in the classic sense, but their trends and insights posts are the standard reference for cross-model latency, throughput, and price comparisons. Check it whenever you need to justify a model choice with numbers instead of opinion.`,tags:[`web`,`publication`,`intermediate`],subsection:`Hidden gems`,gem:!0}],totalItems:41},{slug:`twitter`,label:`Who to follow`,description:`Verified X/Twitter accounts worth following — frontier-lab researchers, open-source builders, GPU people, paper feeds.`,subsections:[`Frontier-lab researchers`,`Open-source & fine-tuning builders`,`Educators & explainers`,`Inference & GPU/systems`,`Evals & analysis`,`AI engineering practitioners`,`Paper-feed accounts`,`Hidden gems`],items:[{name:`@_sholtodouglas`,url:`https://x.com/_sholtodouglas`,blurb:`One of the clearest public voices on what actually makes models better at scale. Writes long, generous threads and podcast follow-ups on RL, context length, and why serving constraints shape model design.`,tags:[`Scaling RL at Anthropic, ex-DeepMind`,`RL scaling, long context, inference economics`],subsection:`Frontier-lab researchers`,gem:!1},{name:`@ch402`,url:`https://x.com/ch402`,blurb:`Co-founder of the modern interpretability agenda (Distill, circuits, superposition). Posts when there's a real result, and explains it better than the paper does.`,tags:[`Chris Olah, interpretability at Anthropic`,`mech interp, features, superposition`],subsection:`Frontier-lab researchers`,gem:!1},{name:`@TrentonBricken`,url:`https://x.com/TrentonBricken`,blurb:`Smaller account, high density. Good for understanding what interp findings mean rather than just that they happened.`,tags:[`Anthropic interpretability`,`circuits, model internals, neuroscience analogies`],subsection:`Frontier-lab researchers`,gem:!1},{name:`@NeelNanda5`,url:`https://x.com/NeelNanda5`,blurb:`Unusually willing to post "here's why the field's last idea didn't pan out." Also the best single source on how to break into interpretability research.`,tags:[`Mech interp lead at Google DeepMind`,`interp research, career advice, honest self-critique`],subsection:`Frontier-lab researchers`,gem:!1},{name:`@AmandaAskell`,url:`https://x.com/AmandaAskell`,blurb:`Shapes Claude's personality and writes about it publicly. If you care about how a model's persona and system prompt are actually designed, this is the primary source.`,tags:[`Philosopher/ethicist at Anthropic`,`model character, system prompts, AI ethics`],subsection:`Frontier-lab researchers`,gem:!1},{name:`@janleike`,url:`https://x.com/janleike`,blurb:`Posts concrete alignment results and challenges rather than vibes. Runs public jailbreak bounties from this account.`,tags:[`Alignment research at Anthropic, ex-OpenAI/DeepMind`,`alignment, safety cases, red-teaming`],subsection:`Frontier-lab researchers`,gem:!1},{name:`@jackclarkSF`,url:`https://x.com/jackclarkSF`,blurb:`Writes the Import AI newsletter; the account is where its arguments get road-tested. The best policy-literate technical account on the platform.`,tags:[`Anthropic co-founder, policy`,`AI policy, compute trends, Import AI`],subsection:`Frontier-lab researchers`,gem:!1},{name:`@polynoamial`,url:`https://x.com/polynoamial`,blurb:`Co-created superhuman poker AI, then helped build the reasoning-model paradigm. Explains why scaling inference-time compute works.`,tags:[`Reasoning research at OpenAI`,`test-time compute, RL for reasoning, game AI`],subsection:`Frontier-lab researchers`,gem:!1},{name:`@aidan_mclau`,url:`https://x.com/aidan_mclau`,blurb:`Extremely prolific and opinionated. Follow for the practitioner's view of what post-training changes about a model's behavior — expect a lot of noise alongside the signal.`,tags:[`Post-training research at OpenAI`,`post-training, model taste, benchmarks vs. feel`],subsection:`Frontier-lab researchers`,gem:!1},{name:`@_jasonwei`,url:`https://x.com/_jasonwei`,blurb:`First author on chain-of-thought prompting and emergent abilities. Posts essay-length reflections on how to pick research problems that hold up.`,tags:[`AI researcher at Meta, ex-OpenAI/Google`,`chain-of-thought, emergence, research taste`],subsection:`Frontier-lab researchers`,gem:!1},{name:`@danielhanchen`,url:`https://x.com/danielhanchen`,blurb:`Reliably the first person to find the broken chat template, tokenizer bug, or bad RoPE config in a new open-weights release, and he posts the fix. Worth following for that alone.`,tags:[`Unsloth co-founder`,`fine-tuning, quantization, bug hunts in new model releases`],subsection:`Open-source & fine-tuning builders`,gem:!1},{name:`@UnslothAI`,url:`https://x.com/UnslothAI`,blurb:`The org account: runnable Colab notebooks and dynamic quants within hours of a major release. Your fastest path from "model dropped" to "I fine-tuned it."`,tags:[`Fine-tuning framework`,`LoRA/QLoRA notebooks, GGUF quants, day-one model support`],subsection:`Open-source & fine-tuning builders`,gem:!1},{name:`@Teknium`,url:`https://x.com/Teknium`,blurb:"Note the handle — it's `@Teknium`, not `@Teknium1`. Built the Hermes model line; posts openly about dataset construction and post-training choices most labs keep private.",tags:[`Co-founder & lead engineer, Nous Research`,`open post-training, synthetic data, agent models`],subsection:`Open-source & fine-tuning builders`,gem:!1},{name:`@winglian`,url:`https://x.com/winglian`,blurb:`Maintains the most-used open fine-tuning framework. Small account, but it's where you learn which training configs actually converge.`,tags:[`Founder/maintainer, Axolotl`,`fine-tuning configs, training recipes, OSS maintenance`],subsection:`Open-source & fine-tuning builders`,gem:!1},{name:`@maximelabonne`,url:`https://x.com/maximelabonne`,blurb:`Author of the widely used open LLM Course and hands-on guides to merging and uncensoring models. Turns techniques into notebooks you can run.`,tags:[`Head of Post-Training at Liquid AI`,`model merging, abliteration, the LLM Course`],subsection:`Open-source & fine-tuning builders`,gem:!1},{name:`@_lewtun`,url:`https://x.com/_lewtun`,blurb:`Works on TRL and open reproductions of reasoning models. Posts the recipe, the hyperparameters, and what failed.`,tags:[`Post-training at Hugging Face`,`TRL, open RLHF/GRPO recipes, reproductions`],subsection:`Open-source & fine-tuning builders`,gem:!1},{name:`@eliebakouch`,url:`https://x.com/eliebakouch`,blurb:`Co-author on Hugging Face's ultra-scale training material. One of the few people posting pretraining detail at this resolution.`,tags:[`Training LLMs at Prime Intellect, ex-Hugging Face`,`pretraining internals, data pipelines, scaling`],subsection:`Open-source & fine-tuning builders`,gem:!1},{name:`@natolambert`,url:`https://x.com/natolambert`,blurb:`Writes Interconnects and the RLHF book. The most consistent analyst of what open models can and can't close the gap on.`,tags:[`Open-model research, ex-Ai2 OLMo`,`RLHF, open-model strategy, Interconnects`],subsection:`Open-source & fine-tuning builders`,gem:!1},{name:`@karpathy`,url:`https://x.com/karpathy`,blurb:`The single highest-value follow for someone moving into AI engineering. Ships teaching repos (nanoGPT, nanochat) and reframes how to think about LLMs in a way that sticks.`,tags:[`Ex-Tesla AI director, ex-OpenAI founding member`,`LLM mental models, from-scratch code, teaching`],subsection:`Educators & explainers`,gem:!1},{name:`@rasbt`,url:`https://x.com/rasbt`,blurb:`Author of Build a Large Language Model (From Scratch). Posts careful side-by-side comparisons of new model architectures with actual code.`,tags:[`Sebastian Raschka, ML researcher & author`,`architecture breakdowns, from-scratch implementations`],subsection:`Educators & explainers`,gem:!1},{name:`@simonw`,url:`https://x.com/simonw`,blurb:`Documents everything he tries with LLMs in public, including what fails. The best account for the working-engineer view of the tools, and the loudest sane voice on prompt injection.`,tags:[`Creator of Datasette, co-creator of Django`,`practical LLM use, tooling, prompt injection`],subsection:`Educators & explainers`,gem:!1},{name:`@jeremyphoward`,url:`https://x.com/jeremyphoward`,blurb:`Taught a generation of engineers to train models. Now posts on Answer.AI's tools and on keeping AI development open.`,tags:[`Co-founder, fast.ai and Answer.AI`,`teaching, practical deep learning, open-source advocacy`],subsection:`Educators & explainers`,gem:!1},{name:`@cwolferesearch`,url:`https://x.com/cwolferesearch`,blurb:`Writes the long survey threads — twenty papers on one topic, synthesized. Excellent for catching up on a subfield in one sitting.`,tags:[`Research at Netflix, writes Deep (Learning) Focus`,`literature-review threads, RL, agents`],subsection:`Educators & explainers`,gem:!1},{name:`@giffmana`,url:`https://x.com/giffmana`,blurb:`Co-author on ViT and SigLIP. Will publicly explain why a hyped paper's claim doesn't hold, which is rarer and more useful than it should be.`,tags:[`Lucas Beyer, researcher at Meta (ex-OpenAI, DeepMind, Brain)`,`vision/multimodal, blunt paper critique`],subsection:`Educators & explainers`,gem:!1},{name:`@srush_nlp`,url:`https://x.com/srush_nlp`,blurb:`Built The Annotated Transformer, GPU Puzzles, and Tensor Puzzles. If you learn by solving small exercises, follow for the drops.`,tags:[`Sasha Rush, researcher at Cursor`,`annotated papers, GPU/tensor puzzles, teaching`],subsection:`Educators & explainers`,gem:!1},{name:`@ProfTomYeh`,url:`https://x.com/ProfTomYeh`,blurb:`Works attention, backprop, and transformer math out by hand on paper. Underrated for actually internalizing the shapes instead of trusting the library.`,tags:[`CS professor, "AI by Hand"`,`hand-worked matrix math for transformers`],subsection:`Educators & explainers`,gem:!1},{name:`@tri_dao`,url:`https://x.com/tri_dao`,blurb:`Author of FlashAttention and co-author of Mamba. Posts when a kernel or architecture result lands; the threads explain the memory-hierarchy reasoning behind them.`,tags:[`Princeton professor, Chief Scientist at Together AI`,`FlashAttention, Mamba, efficient architectures`],subsection:`Inference & GPU/systems`,gem:!1},{name:`@cHHillee`,url:`https://x.com/cHHillee`,blurb:`The person to read on why your model is slow. Wrote the canonical "making deep learning go brrr" material and the recent work on batch-invariant, reproducible inference.`,tags:[`Horace He, Thinking Machines, formerly PyTorch`,`GPU performance, roofline analysis, determinism`],subsection:`Inference & GPU/systems`,gem:!1},{name:`@vllm_project`,url:`https://x.com/vllm_project`,blurb:`Follow to know what production serving supports this week — new models, quantization formats, scheduler and KV-cache changes.`,tags:[`vLLM inference engine`,`serving throughput, releases, feature support`],subsection:`Inference & GPU/systems`,gem:!1},{name:`@woosuk_k`,url:`https://x.com/woosuk_k`,blurb:`Small account, deep detail. Posts the design reasoning behind vLLM's scheduler and memory management, which is the best free education in inference systems.`,tags:[`vLLM co-creator`,`PagedAttention, KV cache, serving internals`],subsection:`Inference & GPU/systems`,gem:!1},{name:`@sgl_project`,url:`https://x.com/sgl_project`,blurb:`The other serious open serving stack, strong on structured output and prefix reuse. Useful counterweight to reading only vLLM's framing.`,tags:[`SGLang inference engine`,`RadixAttention, prefix caching, large-scale serving`],subsection:`Inference & GPU/systems`,gem:!1},{name:`@marksaroufim`,url:`https://x.com/marksaroufim`,blurb:`Runs the GPU MODE community. Posts kernel-writing material and pushes people to learn GPUs by actually profiling something.`,tags:[`GPU MODE co-founder, ex-PyTorch`,`CUDA kernels, quantization, performance culture`],subsection:`Inference & GPU/systems`,gem:!1},{name:`@GPU_MODE`,url:`https://x.com/GPU_MODE`,blurb:`The org account for the best free GPU-programming curriculum around. Follow for lecture drops and leaderboard problems.`,tags:[`GPU programming community`,`lecture series, kernel competitions, CUDA/Triton`],subsection:`Inference & GPU/systems`,gem:!1},{name:`@Tim_Dettmers`,url:`https://x.com/Tim_Dettmers`,blurb:`Wrote QLoRA and bitsandbytes. Also the author of the GPU-selection guide most people still use when speccing a machine.`,tags:[`Creator of bitsandbytes, CMU professor, Ai2`,`quantization, QLoRA, GPU buying advice`],subsection:`Inference & GPU/systems`,gem:!1},{name:`@ggerganov`,url:`https://x.com/ggerganov`,blurb:`Local inference for the rest of us. Follow to track what's now feasible to run on a laptop or a phone.`,tags:[`Creator of llama.cpp and whisper.cpp`,`local inference, C/C++ implementations, GGUF`],subsection:`Inference & GPU/systems`,gem:!1},{name:`@arena`,url:`https://x.com/arena`,blurb:"This is LMArena's current account — the old `@lmarena_ai` handle is a stub that points here. Leaderboard shifts and stealth-model sightings land here first.",tags:[`LMArena / Arena.ai`,`human-preference leaderboards, model launches`],subsection:`Evals & analysis`,gem:!1},{name:`@ArtificialAnlys`,url:`https://x.com/ArtificialAnlys`,blurb:`The account to check before picking a model or an inference provider. They benchmark the same model across hosts, which surfaces real serving quality differences.`,tags:[`Independent AI benchmarking firm`,`quality/price/latency comparisons, provider benchmarks`],subsection:`Evals & analysis`,gem:!1},{name:`@EpochAIResearch`,url:`https://x.com/EpochAIResearch`,blurb:`Rigorous quantitative work on training compute, algorithmic progress, and hard math benchmarks. The antidote to vibes-based capability forecasting.`,tags:[`Epoch AI`,`compute trends, scaling data, FrontierMath`],subsection:`Evals & analysis`,gem:!1},{name:`@METR_Evals`,url:`https://x.com/METR_Evals`,blurb:`Produced the "length of tasks AI can complete" doubling-time result. The most methodologically careful public work on agent capability over time.`,tags:[`METR`,`autonomy evals, task-horizon measurement`],subsection:`Evals & analysis`,gem:!1},{name:`@arcprize`,url:`https://x.com/arcprize`,blurb:`Runs the benchmark that frontier labs still can't saturate cheaply. Good for a grounded read on what "reasoning" progress means.`,tags:[`ARC Prize Foundation`,`ARC-AGI benchmarks, reasoning evaluation`],subsection:`Evals & analysis`,gem:!1},{name:`@hendrycks`,url:`https://x.com/hendrycks`,blurb:`Created MMLU, MATH, and Humanity's Last Exam. Posts on benchmark design and safety with a contrarian streak worth reading.`,tags:[`Dan Hendrycks, CAIS director`,`benchmark design, AI safety, risk analysis`],subsection:`Evals & analysis`,gem:!1},{name:`@LechMazur`,url:`https://x.com/LechMazur`,blurb:`Runs a suite of idiosyncratic benchmarks (social deduction, NYT Connections, confabulation) that probe things standard evals miss. Great for spotting model personality differences.`,tags:[`Independent benchmarker`,`custom LLM benchmarks, elimination games, creative writing evals`],subsection:`Evals & analysis`,gem:!1},{name:`@paulgauthier`,url:`https://x.com/paulgauthier`,blurb:`Maintains the Aider polyglot leaderboard, one of the more honest measures of real code-editing ability. Posts results the day new coding models land.`,tags:[`Creator of Aider`,`code-editing benchmarks, coding-agent evals`],subsection:`Evals & analysis`,gem:!1},{name:`@swyx`,url:`https://x.com/swyx`,blurb:`Coined "AI Engineer" and built the community around it. The best single account for a map of the field rather than a slice of it.`,tags:[`Latent Space, AI Engineer conference`,`the AI engineering discipline, conference talks, synthesis`],subsection:`AI engineering practitioners`,gem:!1},{name:`@HamelHusain`,url:`https://x.com/HamelHusain`,blurb:`Bio is literally "Evals Evals Evals." Teaches the unglamorous discipline — look at your data, build error analysis — that separates working LLM products from demos.`,tags:[`Independent consultant, evals educator`,`LLM evals, error analysis, RAG debugging`],subsection:`AI engineering practitioners`,gem:!1},{name:`@eugeneyan`,url:`https://x.com/eugeneyan`,blurb:`Writes long, well-organized essays on shipping ML systems. Rare combination of production experience and clear teaching.`,tags:[`MTS at Anthropic, ex-Amazon principal scientist`,`applied ML writeups, RecSys, evals`],subsection:`AI engineering practitioners`,gem:!1},{name:`@chipro`,url:`https://x.com/chipro`,blurb:`Wrote the AI Engineering and Designing ML Systems books. Posts infrequently but substantively — usually a distilled chunk of a chapter.`,tags:[`Chip Huyen, author of AI Engineering`,`system design, ML in production, book-length synthesis`],subsection:`AI engineering practitioners`,gem:!1},{name:`@lateinteraction`,url:`https://x.com/lateinteraction`,blurb:`Created ColBERT and DSPy. Argues consistently that you should compile prompts rather than hand-tune them, and backs it with results.`,tags:[`Omar Khattab, MIT CSAIL professor`,`DSPy, ColBERT, programming vs. prompting`],subsection:`AI engineering practitioners`,gem:!1},{name:`@sh_reya`,url:`https://x.com/sh_reya`,blurb:`Bridges research and practice on evaluating LLM pipelines. Posts findings on why prompt-based pipelines fail in ways teams don't notice.`,tags:[`Shreya Shankar, incoming CMU professor`,`LLM pipeline evaluation, data systems, DocETL`],subsection:`AI engineering practitioners`,gem:!1},{name:`@willccbb`,url:`https://x.com/willccbb`,blurb:`Central to the open RL-environments push. If you want to actually run RL on a task of your own, his tooling and threads are the entry point.`,tags:[`Prime Intellect, creator of verifiers`,`RL environments, GRPO, open RL infrastructure`],subsection:`AI engineering practitioners`,gem:!1},{name:`@dexhorthy`,url:`https://x.com/dexhorthy`,blurb:`Wrote the 12-Factor Agents principles. Practical, hype-free framing of how to structure agents that survive contact with production.`,tags:[`Founder, HumanLayer`,`12-factor agents, context engineering, agent architecture`],subsection:`AI engineering practitioners`,gem:!1},{name:`@charles_irl`,url:`https://x.com/charles_irl`,blurb:`Behind Modal's GPU Glossary, one of the best free explainers of GPU architecture. Posts on what inference actually costs and why.`,tags:[`Modal`,`GPU glossary, inference economics, serverless GPU`],subsection:`AI engineering practitioners`,gem:!1},{name:`@_akhaliq`,url:`https://x.com/_akhaliq`,blurb:`The highest-volume paper feed on the platform (47k+ posts). Skim the titles, ignore the promo. Best raw discovery source.`,tags:[`AK, Hugging Face`,`daily arXiv paper posts`],subsection:`Paper-feed accounts`,gem:!1},{name:`@arankomatsuzaki`,url:`https://x.com/arankomatsuzaki`,blurb:`Lower volume than AK and more filtered — he adds a line of context explaining why the paper matters. Better signal-to-noise for a daily read.`,tags:[`Independent researcher, ex-GT`,`curated papers with commentary`],subsection:`Paper-feed accounts`,gem:!1},{name:`@dair_ai`,url:`https://x.com/dair_ai`,blurb:`Weekly digest format rather than a firehose. The right pick if you'd rather catch up once a week than scroll daily.`,tags:[`DAIR.AI`,`ML Papers of the Week, prompt engineering guides`],subsection:`Paper-feed accounts`,gem:!1},{name:`@TheAITimeline`,url:`https://x.com/TheAITimeline`,blurb:`Compiles the week's most-discussed papers with summaries. Check the account's highlights tab for the archive.`,tags:[`Research digest account`,`weekly trending-paper roundups`],subsection:`Paper-feed accounts`,gem:!1},{name:`@askalphaxiv`,url:`https://x.com/askalphaxiv`,blurb:`A social layer over arXiv — you see which papers people are actually engaging with, plus author Q&A. Useful for judging impact early.`,tags:[`alphaXiv`,`paper discussion layer, trending arXiv`],subsection:`Paper-feed accounts`,gem:!1},{name:`@nrehiew_`,url:`https://x.com/nrehiew_`,blurb:`Does things like reverse-engineering and reproducing a frontier model's tokenizer, then posting what the vocab size implies about the lab's design choices. Very few followers relative to the depth.`,tags:[`Engineer/researcher, mostly anonymous`,`model internals, reproductions, architecture forensics`],subsection:`Hidden gems`,gem:!0},{name:`@kalomaze`,url:`https://x.com/kalomaze`,blurb:`Invented min_p sampling as an outsider before joining a lab. Posts unfiltered observations about where RL and agent training actually break.`,tags:[`ML researcher at Prime Intellect`,`sampling methods, RL details, agent failure modes`],subsection:`Hidden gems`,gem:!0},{name:`@Dorialexander`,url:`https://x.com/Dorialexander`,blurb:`One of the few people building fully open-data pretraining corpora and writing honestly about the legal and quality tradeoffs. Sharp on EU vs. US vs. China open-model dynamics.`,tags:[`Alexander Doria, Pleias`,`open pretraining data, European AI, data licensing`],subsection:`Hidden gems`,gem:!0},{name:`@gm8xx8`,url:`https://x.com/gm8xx8`,blurb:`Tiny follower count, very high posting volume, and consistently early on open releases that don't get mainstream coverage. Bio says "high-taste AI, open models," and it earns it.`,tags:[`Independent open-model tracker`,`new model releases, papers, open-weights ecosystem`],subsection:`Hidden gems`,gem:!0},{name:`@xenovacom`,url:`https://x.com/xenovacom`,blurb:`Ships demos of real models running entirely in a browser tab. The best account for the on-device/edge corner of AI engineering, which most feeds ignore entirely.`,tags:[`Creator of Transformers.js, Hugging Face`,`in-browser inference, on-device models, WebGPU`],subsection:`Hidden gems`,gem:!0}],totalItems:62},{slug:`papers`,label:`Research papers`,description:`Where to find papers, curated reading lists, and a verified canon of must-reads with exact arXiv links.`,subsections:[`Where to find papers`,`Curated reading lists`,`The canon, verified`,`How to read papers`,`Hidden gems`],items:[{name:`Hugging Face Daily Papers`,url:`https://huggingface.co/papers`,blurb:`The default daily feed, curated by AK and the HF community, with daily/weekly/monthly views. Now also the destination Papers With Code redirects to, which makes it the field's de-facto front page.`,tags:[`platform`,`active`,`discovery`],subsection:`Where to find papers`,gem:!1},{name:`Hugging Face Trending Papers`,url:`https://huggingface.co/papers/trending`,blurb:"Where `paperswithcode.com` actually lands you today. Ranked by community engagement rather than editorial pick, so it is the noisier but broader sibling of Daily Papers.",tags:[`platform`,`active`,`discovery`],subsection:`Where to find papers`,gem:!1},{name:`alphaXiv`,url:`https://www.alphaxiv.org/`,blurb:"A discussion and Q&A layer over arXiv out of Stanford. Swap `arxiv.org` for `alphaxiv.org` in any abstract URL (e.g. `alphaxiv.org/abs/2501.12948`) to get the comment thread and an LLM you can interrogate about that specific paper.",tags:[`platform`,`active`,`discussion`],subsection:`Where to find papers`,gem:!1},{name:`Semantic Scholar`,url:`https://www.semanticscholar.org/`,blurb:`Ai2's index of ~200M papers with citation contexts, influential-citation counts, and a genuinely usable free API. The right tool when you need to trace who cited what and why.`,tags:[`platform`,`active`,`search`],subsection:`Where to find papers`,gem:!1},{name:`Connected Papers`,url:`https://www.connectedpapers.com/`,blurb:`Give it one paper, get a similarity graph of its neighborhood. The fastest way to go from "I found one relevant paper" to "I understand this subfield's shape."`,tags:[`tool`,`active`,`discovery`],subsection:`Where to find papers`,gem:!1},{name:`Emergent Mind`,url:`https://www.emergentmind.com/`,blurb:`Tracks which arXiv papers are catching fire on social media, with generated overviews and filters by day/week/month/year. Good signal-to-noise when you want the papers people are actually arguing about.`,tags:[`platform`,`active`,`discovery`],subsection:`Where to find papers`,gem:!1},{name:`OpenReview`,url:`https://openreview.net/`,blurb:`ICLR, NeurIPS, and friends host open peer review here. Reading the reviewer objections and author rebuttals on a paper you care about is often more instructive than the paper.`,tags:[`platform`,`active`,`peer-review`],subsection:`Where to find papers`,gem:!1},{name:`arXiv cs.LG / cs.CL listings`,url:`https://arxiv.org/list/cs.LG/recent`,blurb:`The raw feed. Unmanageable to read directly, but the ground truth every other tool on this list is derived from, and worth knowing how to filter.`,tags:[`source`,`active`,`firehose`],subsection:`Where to find papers`,gem:!1},{name:`Papers with Code (community revival)`,url:`https://paperswithcode.co/`,blurb:"Rebuilt at the `.co` domain by Niels Rogge of Hugging Face after Meta sunset the original on 24 July 2025. Restores the paper-to-code and SOTA-leaderboard model the original was loved for.",tags:[`platform`,`active`,`sota`],subsection:`Where to find papers`,gem:!1},{name:`Zeta Alpha blog / Trends in AI`,url:`https://www.zeta-alpha.com/blog`,blurb:'The company pivoted to enterprise search, but the monthly Trends in AI write-up and webinar survive and are one of the better "what shifted this month, with citations" reads. (Their old `/trends` page is gone; the blog is the live entry point.)',tags:[`newsletter`,`active`,`analysis`],subsection:`Where to find papers`,gem:!1},{name:`arxiv-sanity-lite (source only)`,url:`https://github.com/karpathy/arxiv-sanity-lite`,blurb:"Karpathy's tag-and-recommend reader over arXiv abstracts. The hosted site `arxiv-sanity-lite.com` no longer responds (`arxiv-sanity.com` redirects to the dead host), but the MIT-licensed code still runs — he documented it on a $5/month VPS.",tags:[`tool`,`site-down`,`self-host`],subsection:`Where to find papers`,gem:!1},{name:`Ilya Sutskever's ~30 papers`,url:`https://github.com/dzyim/ilya-sutskever-recommended-reading`,blurb:`The list Sutskever reportedly gave John Carmack with "if you really learn all of these, you'll know 90% of what matters today." This repo is the most maintained transcription, with working links per paper.`,tags:[`list`,`2024`,`foundations`],subsection:`Curated reading lists`,gem:!1},{name:`30papers.com`,url:`https://30papers.com/`,blurb:`The same Sutskever list as a clean browsable site rather than a README. Better if you want to work through it rather than clone it.`,tags:[`list`,`active`,`foundations`],subsection:`Curated reading lists`,gem:!1},{name:`Aman's AI Journal: Sutskever's Top 30`,url:`https://aman.ai/primers/ai/top-30-papers/`,blurb:`Each paper on the Sutskever list with an actual distilled summary attached, so you can triage which ones you need to read in full. The wider aman.ai primers are the strongest free set of ML explainers nobody talks about.`,tags:[`list`,`active`,`foundations`],subsection:`Curated reading lists`,gem:!1},{name:`The 2025 AI Engineering Reading List`,url:`https://www.latent.space/p/2025-papers`,blurb:`Latent Space's 50 papers across 10 sections (frontier LLMs, evals, prompting, RAG, agents, codegen, vision, voice, diffusion, finetuning). The single best-targeted list for someone moving from software engineering into AI engineering.`,tags:[`list`,`2024`,`ai-engineering`],subsection:`Curated reading lists`,gem:!1},{name:`Key Papers in Deep RL (Spinning Up)`,url:`https://spinningup.openai.com/en/latest/spinningup/keypapers.html`,blurb:`OpenAI's structured RL canon across 13 areas from model-free RL through safety and imitation learning. Still the reference map for RL, which matters again now that post-training is RL.`,tags:[`list`,`active`,`rl`],subsection:`Curated reading lists`,gem:!1},{name:`Neel Nanda's favourite mech-interp papers`,url:`https://www.neelnanda.io/mechanistic-interpretability/favourite-papers-old`,blurb:`Extremely opinionated and annotated: which sections to read deeply, which to skim, which to skip outright, plus his disagreements with each. Priority-ordered into four tiers.`,tags:[`list`,`active`,`interpretability`],subsection:`Curated reading lists`,gem:!1},{name:`AI Papers of the Week`,url:`https://github.com/dair-ai/ml-papers-of-the-week`,blurb:`DAIR.AI has shipped a weekly top-papers roundup since 2023 without missing a beat, with archives by year. Use it as the ongoing feed once you've cleared a foundational list.`,tags:[`list`,`active`,`weekly`],subsection:`Curated reading lists`,gem:!1},{name:`Awesome-LLM`,url:`https://github.com/Hannibal046/Awesome-LLM`,blurb:`The LLM awesome-list that stayed maintained while most died: milestone papers, open models, training/deployment tooling, courses. Better as a lookup table than a syllabus.`,tags:[`list`,`active`,`reference`],subsection:`Curated reading lists`,gem:!1},{name:`Transformer Circuits Thread`,url:`https://transformer-circuits.pub/`,blurb:`Anthropic's interpretability output published as a running thread of interactive articles rather than arXiv PDFs. Read in order it is effectively a course in reverse-engineering transformers.`,tags:[`list`,`active`,`interpretability`],subsection:`Curated reading lists`,gem:!1},{name:`Attention Is All You Need`,url:`https://arxiv.org/abs/1706.03762`,blurb:`The transformer. Everything downstream on this list is a modification of, a scaling of, or a reaction to this eight-page paper.`,tags:[`paper`,`2017`,`architecture`],subsection:`The canon, verified`,gem:!1},{name:`BERT`,url:`https://arxiv.org/abs/1810.04805`,blurb:`Bidirectional masked-language-model pretraining, and the paper that made "pretrain then fine-tune" the default. Still the mental model behind every embedding model you use.`,tags:[`paper`,`2018`,`pretraining`],subsection:`The canon, verified`,gem:!1},{name:`Language Models are Few-Shot Learners (GPT-3)`,url:`https://arxiv.org/abs/2005.14165`,blurb:`175B parameters, and the discovery that scale alone buys in-context learning. This is where prompting became a discipline instead of a curiosity.`,tags:[`paper`,`2020`,`llm`],subsection:`The canon, verified`,gem:!1},{name:`Scaling Laws for Neural Language Models`,url:`https://arxiv.org/abs/2001.08361`,blurb:`Kaplan et al. showed loss falls as a smooth power law in compute, data, and parameters. It turned model training from craft into budgeting.`,tags:[`paper`,`2020`,`scaling`],subsection:`The canon, verified`,gem:!1},{name:`Training Compute-Optimal Large Language Models (Chinchilla)`,url:`https://arxiv.org/abs/2203.15556`,blurb:`DeepMind's correction to Kaplan: models of that era were badly undertrained on data. The ~20-tokens-per-parameter rule reshaped every training run that followed.`,tags:[`paper`,`2022`,`scaling`],subsection:`The canon, verified`,gem:!1},{name:`Training language models to follow instructions with human feedback`,url:`https://arxiv.org/abs/2203.02155`,blurb:`InstructGPT — the RLHF recipe that turned a text predictor into an assistant, and the direct ancestor of ChatGPT. A 1.3B aligned model beat 175B unaligned on human preference.`,tags:[`paper`,`2022`,`rlhf`],subsection:`The canon, verified`,gem:!1},{name:`Constitutional AI: Harmlessness from AI Feedback`,url:`https://arxiv.org/abs/2212.08073`,blurb:`Anthropic replaces human harmlessness labels with a model critiquing itself against a written constitution. The origin of RLAIF and of "principles as a config file."`,tags:[`paper`,`2022`,`alignment`],subsection:`The canon, verified`,gem:!1},{name:`Direct Preference Optimization`,url:`https://arxiv.org/abs/2305.18290`,blurb:`Shows your LM is already implicitly a reward model, so you can skip the reward model and the RL loop entirely. DPO is why preference tuning became something a small team can do.`,tags:[`paper`,`2023`,`post-training`],subsection:`The canon, verified`,gem:!1},{name:`Chain-of-Thought Prompting`,url:`https://arxiv.org/abs/2201.11903`,blurb:`"Let's think step by step" as a research result. The paper that established reasoning as something you elicit at inference time, later absorbed into the models themselves.`,tags:[`paper`,`2022`,`prompting`],subsection:`The canon, verified`,gem:!1},{name:`ReAct: Synergizing Reasoning and Acting`,url:`https://arxiv.org/abs/2210.03629`,blurb:`Interleaves reasoning traces with tool calls in a single loop. Essentially every agent framework shipped since is a ReAct loop with better ergonomics.`,tags:[`paper`,`2022`,`agents`],subsection:`The canon, verified`,gem:!1},{name:`Toolformer`,url:`https://arxiv.org/abs/2302.04761`,blurb:`A model teaches itself when to call which API, via self-supervision rather than annotation. The conceptual root of function calling and MCP.`,tags:[`paper`,`2023`,`tool-use`],subsection:`The canon, verified`,gem:!1},{name:`Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks`,url:`https://arxiv.org/abs/2005.11401`,blurb:`Lewis et al., the paper that named RAG. Predates the products by three years and is still the clearest statement of why parametric and non-parametric memory should be split.`,tags:[`paper`,`2020`,`rag`],subsection:`The canon, verified`,gem:!1},{name:`LoRA: Low-Rank Adaptation`,url:`https://arxiv.org/abs/2106.09685`,blurb:`Freeze the weights, train two small low-rank matrices. The reason fine-tuning a large model is a consumer-hardware activity and adapters can be swapped at serve time.`,tags:[`paper`,`2021`,`finetuning`],subsection:`The canon, verified`,gem:!1},{name:`QLoRA: Efficient Finetuning of Quantized LLMs`,url:`https://arxiv.org/abs/2305.14314`,blurb:`4-bit NormalFloat plus paged optimizers plus LoRA, fine-tuning a 65B model on one 48GB GPU. The paper that put frontier-scale fine-tuning in reach of individuals.`,tags:[`paper`,`2023`,`finetuning`],subsection:`The canon, verified`,gem:!1},{name:`FlashAttention`,url:`https://arxiv.org/abs/2205.14135`,blurb:`Attention rewritten to be IO-aware about GPU memory hierarchy: exact, not approximate, and several times faster. The canonical demonstration that ML wins often come from systems thinking.`,tags:[`paper`,`2022`,`systems`],subsection:`The canon, verified`,gem:!1},{name:`Efficient Memory Management with PagedAttention (vLLM)`,url:`https://arxiv.org/abs/2309.06180`,blurb:`Applies OS virtual-memory paging to the KV cache, cutting waste to near zero and raising throughput 2-4x. This paper is vLLM, which is what is probably serving your model.`,tags:[`paper`,`2023`,`serving`],subsection:`The canon, verified`,gem:!1},{name:`Fast Inference from Transformers via Speculative Decoding`,url:`https://arxiv.org/abs/2211.17192`,blurb:`A small draft model proposes tokens, the big model verifies them in parallel, output distribution unchanged. Free latency, now standard in every serious inference stack.`,tags:[`paper`,`2022`,`inference`],subsection:`The canon, verified`,gem:!1},{name:`Switch Transformers`,url:`https://arxiv.org/abs/2101.03961`,blurb:`Sparse mixture-of-experts taken to a trillion parameters by routing each token to one expert. Made "parameters" and "compute per token" separable, which is now how frontier models are built.`,tags:[`paper`,`2021`,`moe`],subsection:`The canon, verified`,gem:!1},{name:`Mixtral of Experts`,url:`https://arxiv.org/abs/2401.04088`,blurb:`Mistral's sparse MoE with open weights: 47B total, 13B active, beating Llama 2 70B. The paper that made MoE concrete for people outside the big labs.`,tags:[`paper`,`2024`,`moe`],subsection:`The canon, verified`,gem:!1},{name:`Mamba: Linear-Time Sequence Modeling`,url:`https://arxiv.org/abs/2312.00752`,blurb:`Selective state space models with linear-time scaling in sequence length, competitive with transformers. The most credible non-attention challenger, and now a component in production hybrid architectures.`,tags:[`paper`,`2023`,`architecture`],subsection:`The canon, verified`,gem:!1},{name:`An Image is Worth 16x16 Words (ViT)`,url:`https://arxiv.org/abs/2010.11929`,blurb:`Chop an image into patches, feed them to a plain transformer, beat CNNs. The unification step that made today's multimodal models architecturally possible.`,tags:[`paper`,`2020`,`vision`],subsection:`The canon, verified`,gem:!1},{name:`CLIP`,url:`https://arxiv.org/abs/2103.00020`,blurb:`Contrastive training on 400M image-text pairs yields zero-shot classification and a shared embedding space. Underpins image search, Stable Diffusion's conditioning, and most multimodal retrieval.`,tags:[`paper`,`2021`,`multimodal`],subsection:`The canon, verified`,gem:!1},{name:`Denoising Diffusion Probabilistic Models`,url:`https://arxiv.org/abs/2006.11239`,blurb:`Ho et al. made diffusion work, and every image and video generator since is downstream. The one paper on this list where the math genuinely rewards a careful read.`,tags:[`paper`,`2020`,`diffusion`],subsection:`The canon, verified`,gem:!1},{name:`GPT-4 Technical Report`,url:`https://arxiv.org/abs/2303.08774`,blurb:`Canonical for what it refuses to say: no architecture, no data, no training details. The document that marked the end of frontier labs publishing their methods.`,tags:[`report`,`2023`,`frontier`],subsection:`The canon, verified`,gem:!1},{name:`The Llama 3 Herd of Models`,url:`https://arxiv.org/abs/2407.21783`,blurb:`The opposite posture — 90+ pages of data curation, scaling, infrastructure failures, and post-training detail. The best single description of how a frontier model gets built.`,tags:[`report`,`2024`,`open-weights`],subsection:`The canon, verified`,gem:!1},{name:`DeepSeek-V3 Technical Report`,url:`https://arxiv.org/abs/2412.19437`,blurb:`671B MoE with 37B active, trained for a fraction of the expected budget via multi-head latent attention and FP8 training. The efficiency ceiling moved here.`,tags:[`report`,`2024`,`open-weights`],subsection:`The canon, verified`,gem:!1},{name:`DeepSeek-R1`,url:`https://arxiv.org/abs/2501.12948`,blurb:`Reasoning emerging from pure RL with verifiable rewards, no supervised reasoning traces required. The paper that democratized reasoning models and reset the field's 2025 agenda.`,tags:[`report`,`2025`,`reasoning`],subsection:`The canon, verified`,gem:!1},{name:`Qwen3 Technical Report`,url:`https://arxiv.org/abs/2505.09388`,blurb:`Dense and MoE models from 0.6B to 235B with thinking and non-thinking modes in one model, across 119 languages. The current reference point for open-weights capability.`,tags:[`report`,`2025`,`open-weights`],subsection:`The canon, verified`,gem:!1},{name:`How to Read a Paper (Keshav)`,url:`https://cseweb.ucsd.edu/~efernandes/teaching/res/keshav-howtoread.pdf`,blurb:`The three-pass method, in six pages. Pass one is five minutes and decides whether there is a pass two. Read this before you read anything else on this page.`,tags:[`guide`,`2007`,`method`],subsection:`How to read papers`,gem:!1},{name:`Andrew Ng on reading research papers (CS230 Lecture 8)`,url:`https://www.youtube.com/watch?v=733m6qBH-jI`,blurb:`Ng's actual workflow for mastering a literature: compile a list, read every paper to 10%, triage, iterate. The career-advice half of the lecture is worth staying for.`,tags:[`video`,`2018`,`method`],subsection:`How to read papers`,gem:!1},{name:`The Annotated Transformer`,url:`https://nlp.seas.harvard.edu/annotated-transformer/`,blurb:`Harvard NLP's line-by-line reimplementation of "Attention Is All You Need" as a runnable notebook. The model for how to read a systems paper: by rebuilding it.`,tags:[`tutorial`,`active`,`deep-dive`],subsection:`How to read papers`,gem:!1},{name:`Ai2 Asta (formerly Paper Finder)`,url:`https://asta.allen.ai/`,blurb:`An LLM agent that decomposes your query, follows citations, and iterates — built for the long tail of hard-to-find papers rather than the popular few. Ai2 open-sources unusually much of how it works.`,tags:[`tool`,`active`,`search`],subsection:`Hidden gems`,gem:!0},{name:`Scholar Inbox`,url:`https://www.scholar-inbox.com/`,blurb:`Free personalized daily digest trained on your paper ratings, plus a "map of science" to solve the cold start. Academic (ACL 2025 demo paper), not a startup funnel.`,tags:[`tool`,`active`,`recommendations`],subsection:`Hidden gems`,gem:!0},{name:`Papers With Code data archive`,url:`https://github.com/paperswithcode/paperswithcode-data`,blurb:`The complete PWC corpus — papers, methods, datasets, evaluation tables — frozen at September 2025 under CC-BY-SA. Several successors were built on this; you can build on it too.`,tags:[`dataset`,`archived`,`historical`],subsection:`Hidden gems`,gem:!0},{name:`CatalyzeX`,url:`https://www.catalyzex.com/`,blurb:`Browser extension that injects code links directly into arXiv, Google Scholar, and Semantic Scholar pages. Replaces the paper-to-code half of PWC without changing where you already read.`,tags:[`tool`,`active`,`code`],subsection:`Hidden gems`,gem:!0},{name:`Emergent World Representations / Othello-GPT writeups`,url:`https://www.neelnanda.io/mechanistic-interpretability/othello`,blurb:`A short case study showing a model trained only on legal moves builds a linear internal board state. The most convincing single answer to "is it just statistics?"`,tags:[`article`,`2023`,`interpretability`],subsection:`Hidden gems`,gem:!0}],totalItems:56},{slug:`communities`,label:`Communities`,description:`Discords, subreddits, forums, Slacks, and paper clubs where the real conversations happen.`,subsections:[`Research Discords`,`Newsletter & podcast communities`,`Subreddits`,`Forums`,`Slack communities`,`Reading groups & paper clubs`,`Hidden gems`],items:[{name:`EleutherAI`,url:`https://www.eleuther.ai/community`,blurb:`The original open-source LLM research collective (GPT-Neo, GPT-J, the Pile, lm-eval-harness). Research happens in public channels — interpretability, scaling laws, training runs — and the project menu lists open issues you can genuinely contribute to. High signal, low chat; read for a week before posting.`,tags:[`discord`,`research community`,`advanced`],subsection:`Research Discords`,gem:!1},{name:`GPU MODE`,url:`https://discord.gg/gpumode`,blurb:`Formerly CUDA MODE. Weekly lectures on GPU programming (CUDA, Triton, distributed PyTorch) plus working groups building open performance projects. Started Dec 2023 and now the default place kernel authors hang out. Lecture materials are public at gpu-mode/lectures — worth working through even if you never post.`,tags:[`discord`,`research community`,`advanced`],subsection:`Research Discords`,gem:!1}],totalItems:31},{slug:`tools`,label:`Tools & practice`,description:`Interactive visualizers, practice puzzles, evals and leaderboards worth studying, and playgrounds.`,subsections:[`Interactive visualizers`,`Practice platforms & puzzles`,`Evals & leaderboards worth studying`,`Playgrounds & model access`,`Hidden gems`],items:[{name:`LLM Visualization`,url:`https://bbycroft.net/llm`,blurb:`Brendan Bycroft's 3D walkthrough of a working GPT — nano-GPT up to GPT-3 — where you scroll through the actual computation and watch individual numbers move through embedding, attention, MLP, and softmax. The single best artifact on the internet for turning "transformer" from a diagram into a mechanism. Start here.`,tags:[`web`,`visualizer`,`intermediate`],subsection:`Interactive visualizers`,gem:!1},{name:`Transformer Explainer`,url:`https://poloclub.github.io/transformer-explainer/`,blurb:`Georgia Tech Polo Club's interactive GPT-2 running live in your browser: type a prompt and watch attention weights, logits, and the temperature knob change the distribution in real time. Complements bbycroft's spatial view with an interactive one — use both.`,tags:[`web`,`visualizer`,`beginner`],subsection:`Interactive visualizers`,gem:!1}],totalItems:34},{slug:`media`,label:`Media & video`,description:`YouTube channels, podcasts, and short-form — beyond the obvious names.`,subsections:[`YouTube — explainers & intuition`,`YouTube — research, papers & frontier tracking`,`YouTube — building & AI engineering`,`Podcasts`,`Instagram & short-form`,`Hidden gems`],items:[{name:`Welch Labs`,url:`https://www.youtube.com/@welchlabs`,blurb:`Cinematic, deeply-researched visual essays on how models actually work, with a strong recent run on LLM limitations (the two-part "Yann LeCun's $1B Bet Against LLMs" is the current flagship). 894K subs, active through mid-2026; the closest thing to 3B1B's production standard applied squarely to modern AI.`,tags:[`youtube`,`explainer`,`intermediate`],subsection:`YouTube — explainers & intuition`,gem:!1},{name:`Artem Kirsanov`,url:`https://www.youtube.com/@ArtemKirsanov`,blurb:`Computational neuroscience meets deep learning, beautifully animated — memory, world models, and what biological brains suggest about architecture. 372K subs, active 2026. Watch this when you want the why behind an architecture rather than the API.`,tags:[`youtube`,`explainer`,`intermediate`],subsection:`YouTube — explainers & intuition`,gem:!1},{name:`Serrano.Academy`,url:`https://www.youtube.com/@SerranoAcademy`,blurb:`Luis Serrano builds intuition before math, one concept at a time — attention in higher dimensions, LoRA, embeddings. 195K subs, uploading through Aug 2026. The best on-ramp if a topic hasn't clicked yet from denser sources.`,tags:[`youtube`,`explainer`,`beginner`],subsection:`YouTube — explainers & intuition`,gem:!1},{name:`CodeEmporium`,url:`https://www.youtube.com/@CodeEmporium`,blurb:`Ajay Halthor works through transformers, embeddings, and multimodal architectures with code and diagrams side by side. 157K subs, posting weekly as of Aug 2026. Good middle ground between hand-wavy and paper-dense.`,tags:[`youtube`,`explainer`,`intermediate`],subsection:`YouTube — explainers & intuition`,gem:!1},{name:`AI Coffee Break with Letitia`,url:`https://www.youtube.com/@AICoffeeBreak`,blurb:`Letitia Parcalabescu (PhD, ML researcher) explains individual papers and techniques — differential privacy, flow matching vs diffusion — in 10-20 tight minutes. 64.6K subs. Note: cadence has slowed noticeably; last upload I could confirm was Nov 2025, so treat it as a strong back catalogue rather than a live feed.`,tags:[`youtube`,`paper-review`,`intermediate`],subsection:`YouTube — explainers & intuition`,gem:!1},{name:`Algorithmic Simplicity`,url:`https://www.youtube.com/@AlgorithmicSimplicity`,blurb:`Unusually clear first-principles derivations of why architectures work at all, rather than how to call them. 77.1K subs. Dormant — last upload Mar 2025 — but the existing videos on transformers and generalization hold up and are worth the archive dive.`,tags:[`youtube`,`explainer`,`advanced`],subsection:`YouTube — explainers & intuition`,gem:!1},{name:`bycloud`,url:`https://www.youtube.com/@bycloudAI`,blurb:`Fast, opinionated breakdowns of brand-new architectures and model releases, with real technical detail under the meme-y presentation. 230K subs, extremely current (Kimi K3 architecture, LongCat 2.0 as of Aug 2026). The best single feed for "what shipped this month and does it matter."`,tags:[`youtube`,`paper-review`,`intermediate`],subsection:`YouTube — research, papers & frontier tracking`,gem:!1},{name:`Google DeepMind`,url:`https://www.youtube.com/@GoogleDeepMind`,blurb:`First-party research announcements, Gemini and robotics demos, and researcher interviews. 914K subs, active 2026. Marketing-adjacent, but the technical deep-dives with actual paper authors are the real draw.`,tags:[`youtube`,`research`,`intermediate`],subsection:`YouTube — research, papers & frontier tracking`,gem:!1},{name:`Anthropic`,url:`https://www.youtube.com/@anthropic-ai`,blurb:`Interpretability walkthroughs, alignment discussions, and Claude engineering content straight from the researchers. 764K subs, active Aug 2026. The interpretability material in particular has no good substitute.`,tags:[`youtube`,`research`,`intermediate`],subsection:`YouTube — research, papers & frontier tracking`,gem:!1},{name:`Stanford Online`,url:`https://www.youtube.com/@stanfordonline`,blurb:`Full university courses posted free — CS229, CS224N, CS336 (Language Modeling from Scratch), optimal control. 1.23M subs, adding lectures through Aug 2026. When you want a semester of rigor instead of a 20-minute video.`,tags:[`youtube`,`lecture`,`advanced`],subsection:`YouTube — research, papers & frontier tracking`,gem:!1},{name:`AI Engineer`,url:`https://www.youtube.com/@aiDotEngineer`,blurb:`The full talk archive from the AI Engineer conferences — evals, agent architectures, RAG-in-production, infra. 617K subs, uploading constantly. Practitioners describing what actually broke in production; arguably the single highest-density source for this job title.`,tags:[`youtube`,`conference-talks`,`intermediate`],subsection:`YouTube — building & AI engineering`,gem:!1},{name:`Sam Witteveen`,url:`https://www.youtube.com/@samwitteveenai`,blurb:`Hands-on walkthroughs of new models, agent frameworks, and routing tools, usually within days of release. 126K subs, active Aug 2026. Consistently technical, consistently skips the hype.`,tags:[`youtube`,`tutorial`,`intermediate`],subsection:`YouTube — building & AI engineering`,gem:!1},{name:`Cole Medin`,url:`https://www.youtube.com/@ColeMedin`,blurb:`End-to-end production agent builds in Python, LangGraph, and n8n, with explicit cost, latency, and failure discussion. 221K subs, active Aug 2026. Shows the debugging, not just the happy path.`,tags:[`youtube`,`tutorial`,`intermediate`],subsection:`YouTube — building & AI engineering`,gem:!1},{name:`LangChain`,url:`https://www.youtube.com/@LangChain`,blurb:`The maintainers' own channel — idiomatic LangGraph state machines, retrieval patterns, agent evaluation. 199K subs, active Aug 2026. Worth it purely to avoid copying outdated patterns from old blog posts.`,tags:[`youtube`,`tutorial`,`intermediate`],subsection:`YouTube — building & AI engineering`,gem:!1},{name:`AssemblyAI`,url:`https://www.youtube.com/@AssemblyAI`,blurb:`A vendor channel that behaves like an education channel: voice agents, streaming pipelines, function calling across providers, eval methodology. 183K subs, active Aug 2026.`,tags:[`youtube`,`tutorial`,`intermediate`],subsection:`YouTube — building & AI engineering`,gem:!1},{name:`DeepLearning.AI`,url:`https://www.youtube.com/@DeepLearningAI`,blurb:`Andrew Ng's org — short courses, "The Batch" news segments, and practitioner interviews. Active Aug 2026. Reliable, structured, and never assumes you already know the jargon.`,tags:[`youtube`,`tutorial`,`beginner`],subsection:`YouTube — building & AI engineering`,gem:!1},{name:`Weights & Biases`,url:`https://www.youtube.com/@WeightsBiases`,blurb:`Home of the Gradient Dissent interview series plus MLOps and evaluation content. 67.4K subs, active Aug 2026. Strong on the unglamorous parts: experiment tracking, reproducibility, and why AI startups burn money.`,tags:[`youtube`,`interview`,`intermediate`],subsection:`YouTube — building & AI engineering`,gem:!1},{name:`IBM Technology`,url:`https://www.youtube.com/@IBMTechnology`,blurb:`Five-to-ten minute whiteboard explainers on RAG, embeddings, vector DBs, agent loops. 1.77M subs, daily uploads. The channel to send a non-engineer teammate who needs to understand what you're shipping.`,tags:[`youtube`,`explainer`,`beginner`],subsection:`YouTube — building & AI engineering`,gem:!1},{name:`Underfitted (Santiago Valdarrama)`,url:`https://www.youtube.com/@underfitted`,blurb:`Practical ML engineering with a strong opinion about what's actually worth learning — plus recent Claude Skills and automation work. 62.1K subs, active mid-2026.`,tags:[`youtube`,`tutorial`,`intermediate`],subsection:`YouTube — building & AI engineering`,gem:!1},{name:`Daniel Bourke`,url:`https://www.youtube.com/@mrdbourke`,blurb:`Long-form PyTorch and small-language-model courses, including multi-hour fine-tuning walkthroughs. 251K subs, active 2026. Patient and thorough; good if you learn by typing along.`,tags:[`youtube`,`tutorial`,`beginner`],subsection:`YouTube — building & AI engineering`,gem:!1},{name:`1littlecoder`,url:`https://www.youtube.com/@1littlecoder`,blurb:`Near-daily coverage of model releases, leaks, and open-source tooling. 111K subs, active mid-2026. Low-commitment way to stay current without reading twelve newsletters.`,tags:[`youtube`,`news`,`beginner`],subsection:`YouTube — building & AI engineering`,gem:!1},{name:`Dwarkesh Podcast`,url:`https://www.dwarkesh.com/podcast`,blurb:`Multi-hour interviews with frontier researchers and lab leaders, prepared at a level almost nobody else attempts — recent episodes include Ryan Greenblatt on AI automating AI research. 1.39M YouTube subs, active Aug 2026. The single best show for understanding where the field thinks it's going.`,tags:[`podcast`,`interview`,`intermediate`],subsection:`Podcasts`,gem:!1},{name:`Latent Space`,url:`https://www.latent.space/podcast`,blurb:`swyx and Alessio Fanelli's show explicitly aimed at AI engineers — evals, agent infrastructure, inference economics, with implementation detail most shows skip. Active Aug 2026. If you only subscribe to one podcast for this career transition, make it this one.`,tags:[`podcast`,`interview`,`intermediate`],subsection:`Podcasts`,gem:!1},{name:`The Cognitive Revolution`,url:`https://www.cognitiverevolution.ai/`,blurb:`Nathan Labenz runs the broadest applied-AI feed going, near-daily, with unusually rigorous model-capability discussion. Active Aug 2026. Recent run includes a two-part on-the-ground series on Chinese AI.`,tags:[`podcast`,`interview`,`intermediate`],subsection:`Podcasts`,gem:!1},{name:`Interconnects`,url:`https://www.interconnects.ai/podcast`,blurb:`Nathan Lambert (Ai2) on open models, post-training recipes, and RLHF — audio essays plus interviews with people who actually train these things. Active Jul 2026. The best source anywhere on open-weights model strategy.`,tags:[`podcast`,`analysis`,`advanced`],subsection:`Podcasts`,gem:!1},{name:`No Priors`,url:`https://www.youtube.com/@NoPriorsPodcast`,blurb:`Sarah Guo and Elad Gil, ~45 minutes weekly, with founders and researchers at the center of whatever just shipped. 91.3K subs, active Aug 2026. Best effort-to-signal ratio of any show here.`,tags:[`podcast`,`interview`,`beginner`],subsection:`Podcasts`,gem:!1},{name:`The TWIML AI Podcast`,url:`https://twimlai.com/podcast/twimlai/`,blurb:`Sam Charrington's long-running practitioner show — the deepest bench of working ML researchers as guests, going back years. 30.5K YouTube subs, active Aug 2026. The archive alone is a research education.`,tags:[`podcast`,`interview`,`advanced`],subsection:`Podcasts`,gem:!1},{name:`Harper Carroll AI`,url:`https://www.instagram.com/harpercarrollai/`,blurb:`620K followers. Stanford CS, ex-Meta AI, led ML at an NVIDIA-acquired startup — she breaks down AI headlines and fundamentals in reels without dumbing them down. The best genuine technical educator on the platform, and the "10 Days of AI Basics" series is a legitimately good primer.`,tags:[`instagram`,`short-form`,`beginner`],subsection:`Instagram & short-form`,gem:!1},{name:`3Blue1Brown`,url:`https://www.instagram.com/3blue1brown/`,blurb:`855K followers. Grant Sanderson's Instagram carries clipped animations from the neural network and transformer series. Listed here only as a short-form surface for material covered elsewhere in this archive — but the attention-mechanism clips work surprisingly well standalone.`,tags:[`instagram`,`short-form`,`intermediate`],subsection:`Instagram & short-form`,gem:!1},{name:`ByteByteGo`,url:`https://www.instagram.com/bytebytego/`,blurb:`537K followers, 387 posts. System design diagrams, increasingly covering AI infrastructure — vector DBs, inference serving, RAG pipelines. The visual explanations are genuinely reusable in your own design docs.`,tags:[`instagram`,`short-form`,`intermediate`],subsection:`Instagram & short-form`,gem:!1},{name:`NVIDIA AI`,url:`https://www.instagram.com/nvidiaai/`,blurb:`405K followers. Hardware and inference announcements, GTC clips, research demos. Marketing-forward, but it's the fastest visual read on where accelerator capability is heading.`,tags:[`instagram`,`news`,`beginner`],subsection:`Instagram & short-form`,gem:!1},{name:`Allie K. Miller`,url:`https://www.instagram.com/alliekmiller/`,blurb:`198K followers, posting constantly. Ex-AWS, ex-IBM — focused on AI strategy, tooling, and career positioning rather than internals. Useful specifically for the "moving into AI engineering" angle: what teams hire for and how the market is shifting.`,tags:[`instagram`,`short-form`,`beginner`],subsection:`Instagram & short-form`,gem:!1},{name:`DeepLearning.AI`,url:`https://www.instagram.com/deeplearningai/`,blurb:`108K followers, 1,826 posts. Course announcements and "The Batch" summaries in visual form. Low noise, reliably accurate — the safest AI-news follow on the platform.`,tags:[`instagram`,`news`,`beginner`],subsection:`Instagram & short-form`,gem:!1},{name:`Krish Naik`,url:`https://www.instagram.com/krishnaik06/`,blurb:`50K followers, 682 posts. Long-running data science and ML educator (large YouTube following) posting career guidance and roadmap content. Practical, India-focused, and honest about what the job market actually rewards.`,tags:[`instagram`,`short-form`,`beginner`],subsection:`Instagram & short-form`,gem:!1},{name:`GPU MODE`,url:`https://www.youtube.com/@GPUMODE`,blurb:`Only 32K subs but 111+ lectures deep into CUDA kernels, Triton, quantization, and inference optimization — taught by the people who write these kernels for a living. Active Aug 2026. If you want to move from calling models to making them fast, this is the single best free resource on the internet.`,tags:[`youtube`,`lecture`,`advanced`],subsection:`Hidden gems`,gem:!0},{name:`Neural Breakdown with AVB`,url:`https://www.youtube.com/@avb_fj`,blurb:`33.5K subs. Hand-illustrated deep dives on NLP, alignment, and small-model fine-tuning that are visually inventive in a way almost nothing else at this scale is. Active mid-2026.`,tags:[`youtube`,`explainer`,`intermediate`],subsection:`Hidden gems`,gem:!0},{name:`Trelis Research`,url:`https://www.youtube.com/@TrelisResearch`,blurb:`26K subs. Ronan McGovern does unusually rigorous, no-fluff walkthroughs of fine-tuning, serving, and evaluating open models — including real cost-per-token analysis. Active Jul 2026. Feels like watching a competent engineer's actual screen.`,tags:[`youtube`,`tutorial`,`advanced`],subsection:`Hidden gems`,gem:!0},{name:`Neel Nanda`,url:`https://www.youtube.com/@neelnanda2469`,blurb:`13.7K subs. The DeepMind mechanistic interpretability lead, posting live paper reviews and safety-case walkthroughs (including a live review of the Claude Opus 4.5 system card). Last confirmed upload Dec 2025 — sporadic, but every video is worth the time if interpretability interests you.`,tags:[`youtube`,`research`,`advanced`],subsection:`Hidden gems`,gem:!0},{name:`Gabriel Mongaras`,url:`https://www.youtube.com/@GabrielMongaras`,blurb:`14.5K subs. Whiteboard-style, math-complete walkthroughs of recent papers — softmax attention expressiveness, diffusion internals — at a depth most paper channels skip. Last upload Jan 2026; irregular but exceptional.`,tags:[`youtube`,`paper-review`,`advanced`],subsection:`Hidden gems`,gem:!0},{name:`Stanford CS336: Language Modeling from Scratch`,url:`https://www.youtube.com/@stanfordonline`,blurb:`Buried inside the Stanford Online channel rather than promoted as its own thing. It's the closest available substitute for building a full LLM stack under supervision — tokenizer through training through inference. Search the channel by course code; it doesn't surface on its own.`,tags:[`youtube`,`lecture`,`advanced`],subsection:`Hidden gems`,gem:!0}],totalItems:40}],r={generated:t,categories:n}}));function a(e){return o.find(t=>t.slug===e)}var o,s=e((()=>{i(),r.generated,o=r.categories,o.reduce((e,t)=>e+(t.totalItems??t.items.length),0)}));export{a as n,s as r,o as t};